    (1, '감산사', 35.7666236, 129.3366913, '경상북도 경주시 외동읍 앞등길 117-20', '경북', FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, '임산부는 참여를 금 합니다. 반려동물과 동반 참가는 불가 합니다. 컵라면, 또는 간식은 절대 지참 하시면 안됩니다.', '예약완료 이후, 날짜 변경은 1회 가능하며, 날짜 변경 후 취소 시 환불 불가합니다 예약 후 3일 이내에 입금이 이루어지지 않을시에는 자동취소 됩니다. 참가자격은 다음사람에게 넘어갑니다. 이점을 양지 해 주시기 바랍니다.', '@temple001', '$2a$10$zFTFyr.64hSAp4DpV7G9hexZvBaDZfAIGemGyz0qVDkNUCoiykFcm', TRUE),
