    (167, '화운사', 37.2528180, 127.1620089, '경기도 용인시 처인구 동백죽전대로 111-14', '경기', FALSE, TRUE, FALSE, TRUE, FALSE, TRUE, '사찰 내에서는 정숙을 유지해 주시고, 예불·공양 등 정해진 프로그램 일정에 맞춰 참여해 주세요. 임산부와 반려동물 동반은 제한되며, 컵라면 등 개인 음식물 반입은 삼가주시기 바랍니다.', '체크인 24시간 전까지 취소하시면 전액 환불됩니다. 체크인 24시간 이내에는 환불이 불가합니다.', '@temple167', '$2a$10$zFTFyr.64hSAp4DpV7G9hexZvBaDZfAIGemGyz0qVDkNUCoiykFcm', TRUE),
    (168, '회암사(양주)', 37.8505301, 127.1077265, '경기도 양주시 회암사길 281', '경기', FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, '사찰 내에서는 정숙을 유지해 주시고, 예불·공양 등 정해진 프로그램 일정에 맞춰 참여해 주세요. 임산부와 반려동물 동반은 제한되며, 컵라면 등 개인 음식물 반입은 삼가주시기 바랍니다.', '체크인 24시간 전까지 취소하시면 전액 환불됩니다. 체크인 24시간 이내에는 환불이 불가합니다.', '@temple168', '$2a$10$zFTFyr.64hSAp4DpV7G9hexZvBaDZfAIGemGyz0qVDkNUCoiykFcm', TRUE),
    (169, '흥국사(고양)', 37.6636889, 126.9399149, '경기도 고양시 덕양구 흥국사길 82', '경기', FALSE, TRUE, FALSE, TRUE, FALSE, TRUE, '사찰 내에서는 정숙을 유지해 주시고, 예불·공양 등 정해진 프로그램 일정에 맞춰 참여해 주세요. 임산부와 반려동물 동반은 제한되며, 컵라면 등 개인 음식물 반입은 삼가주시기 바랍니다.', '체크인 24시간 전까지 취소하시면 전액 환불됩니다. 체크인 24시간 이내에는 환불이 불가합니다.', '@temple169', '$2a$10$zFTFyr.64hSAp4DpV7G9hexZvBaDZfAIGemGyz0qVDkNUCoiykFcm', TRUE),
    (170, '흥국사(여수)', 34.8211501, 127.7002713, '전라남도 여수시 흥국사길 160', '전남', TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, '사찰 내에서는 정숙을 유지해 주시고, 예불·공양 등 정해진 프로그램 일정에 맞춰 참여해 주세요. 임산부와 반려동물 동반은 제한되며, 컵라면 등 개인 음식물 반입은 삼가주시기 바랍니다.', '체크인 24시간 전까지 취소하시면 전액 환불됩니다. 체크인 24시간 이내에는 환불이 불가합니다.', '@temple170', '$2a$10$zFTFyr.64hSAp4DpV7G9hexZvBaDZfAIGemGyz0qVDkNUCoiykFcm', TRUE),
    (171, '희방사', 36.9199750, 128.4570280, '경상북도 영주시 풍기읍 죽령로1720번길 278', '경북', FALSE, TRUE, FALSE, FALSE, FALSE, TRUE, '사찰 내에서는 정숙을 유지해 주시고, 예불·공양 등 정해진 프로그램 일정에 맞춰 참여해 주세요. 임산부와 반려동물 동반은 제한되며, 컵라면 등 개인 음식물 반입은 삼가주시기 바랍니다.', '체크인 24시간 전까지 취소하시면 전액 환불됩니다. 체크인 24시간 이내에는 환불이 불가합니다.', '@temple171', '$2a$10$zFTFyr.64hSAp4DpV7G9hexZvBaDZfAIGemGyz0qVDkNUCoiykFcm', TRUE);


-- #####################################################################
-- 3. 오늘의 불교 한마디 (DAILY_QUOTE)
-- #####################################################################
-- =====================================================================
-- 오늘의 불교 한마디(DAILY_QUOTE) 데이터 (30건)
--
-- 옛 불교 성현들의 가르침을 오늘 읽기 좋게 짧게(최대 3줄) 간추린 것으로,
-- 원문 그대로의 인용이 아니라 뜻을 풀어 정리한 문장입니다. source에는 그 가르침을
-- 남긴 분(또는 그 가르침이 담긴 전통적 화두/경전)을 적었습니다.
-- =====================================================================


INSERT INTO DAILY_QUOTE (content, source) VALUES
('모든 괴로움은 집착에서 비롯되니,\n집착을 놓는 그 자리에\n이미 평안이 있다.', '석가모니 (사성제)'),
('마음이 만들어낸 것이 세상이니,\n마음을 다스리면\n세상도 그와 함께 달라진다.', '원효대사 (일체유심조)'),
('사람의 마음을 있는 그대로 바로 보면\n그 자리에서 곧 부처를 본다.', '달마대사'),
('산은 산이요 물은 물이니,\n있는 그대로를 꾸미지 말고 보라.', '성철스님'),
('무소유란 아무것도 갖지 않음이 아니라,\n불필요한 것을 갖지 않는 것이다.', '법정스님'),
('멈추어야 비로소 보이는 것들이 있으니,\n서두르던 걸음을 잠시 내려놓아라.', '혜민스님'),
('단번에 깨닫더라도 오랜 습관은\n하루아침에 사라지지 않으니,\n깨달은 뒤에도 꾸준히 닦아나가라.', '보조국사 지눌 (돈오점수)'),
('부처를 마음 밖에서 찾지 말라,\n그대의 마음이 이미 부처다.', '경허스님'),
('내가 지은 말과 행동, 생각은\n그대로 다시 나에게 돌아오니,\n오늘의 행동이 곧 내일의 나다.', '석가모니 (업)'),
('물들지 않는 연꽃처럼,\n흔들리되 뿌리내린 자리를 지켜라.', '숫타니파타');

INSERT INTO DAILY_QUOTE (content, source) VALUES
('눈 덮인 들판을 걸어갈 때\n함부로 걷지 마라,\n오늘 남긴 발자국이 뒷사람의 길이 된다.', '서산대사 (답설야중거)'),
('청산은 나를 보고 말없이 살라 하고,\n창공은 나를 보고 티 없이 살라 하네,\n탐욕도 성냄도 내려놓고 살다 가라 하네.', '나옹선사'),
('평상시의 마음, 그것이 곧 도(道)이니\n애써 별다른 것을 찾아 헤매지 말라.', '마조도일선사 (평상심시도)'),
('어디에 있든 그 자리의 주인이 되면,\n서 있는 그곳이 모두 참되다.', '임제선사 (수처작주 입처개진)'),
('오직 모를 뿐,\n그 모르는 마음을 그대로 지켜가라.', '숭산스님'),
('차를 마시는 일과 선을 닦는 일은\n본디 둘이 아니다.', '초의선사 (다선일미)'),
('남을 위해 눈물 흘려본 적 없다면,\n아직 자비를 안다고 말하지 말라.', '용성스님'),
('지금 이 순간의 숨 한 번이\n그대가 가진 전부임을 잊지 말라.', '틱낫한 스님');

INSERT INTO DAILY_QUOTE (content, source) VALUES
('하나 안에 모든 것이 있고,\n모든 것 안에 하나가 있으니,\n너와 나는 본디 둘이 아니다.', '의상대사 (법성게)'),
('돼지의 눈에는 돼지만 보이고,\n부처의 눈에는 부처만 보이니,\n내가 무엇을 보든 그것이 곧 나의 마음이다.', '무학대사'),
('하늘을 이불 삼고 땅을 자리 삼아 누우니,\n산은 베개요 달은 촛불이라,\n온 세상이 본디 내 집 아님이 없다.', '진묵대사'),
('부처님 법은 마음 밖에 있지 않으니,\n밖에서 찾을수록 더욱 멀어진다.', '청담스님'),
('안다고 여기는 그 마음부터 내려놓아야,\n비로소 참으로 보이기 시작한다.', '효봉스님'),
('차라리 자취를 감춘 학이 될지언정,\n말 잘하는 앵무새의 재주는 배우지 않겠다.', '한암스님'),
('괴로움은 누가 준 것이 아니라\n내가 짓고 내가 받는 것이니,\n원망을 내려놓으면 그 자리가 곧 낙(樂)이다.', '법륜스님'),
('자비심은 사치가 아니라\n삶에 반드시 필요한 것이다.', '달라이라마'),
('말없이 꽃 한 송이를 들어 보이니,\n오직 한 사람만이 웃음으로 답했다.', '석가모니와 마하가섭 (염화미소)'),
('많이 들었다는 것을 자랑으로 삼지 말고,\n들은 대로 실천하는가를 늘 돌아보라.', '아난존자'),
('자기를 바로 봅시다,\n남을 이롭게 하는 것이 곧 나를 이롭게 하는 것입니다.', '성철스님 (신년법어)'),
('구하는 마음을 쉬면 그 자리가 곧 편안하니,\n따로 편안함을 구하러 다니지 말라.', '종범스님');


-- #####################################################################
-- 4. 템플스테이 프로그램 (TEMPLE_STAY_PROGRAM)
-- #####################################################################
-- =====================================================================
-- 템플스테이 프로그램 데이터 (TEMPLE_STAY_PROGRAM, 400건)
-- =====================================================================

-- 출처: templestay.com 프로그램 목록 145페이지 전수 수집(2026-09-25 기준). 사진/일정/준비물은 상세 페이지에서 직접 추출.
-- 수집·정리 조건
--   - 일정이 1일차만(당일) 또는 2일차까지(1박2일)인 프로그램만. 2박 이상, 장기(한 달 살기 등) 제외
--   - 운영 종료일이 2026-10-01 이후인 프로그램만
--   - 제목에 인원 표기(N인/N명: 1인 1실, 2인 이상 등)가 있거나 특정 대상자 전용(한국소비자원 연계 등)인 프로그램은 제외
--     (2인 이상 프로그램은 예약 시 최소 인원 검증이 필요한데 아직 없음)
--   - 같은 사찰에서 제목이 비슷한 프로그램은 하나만(방 이름만 다른 건 각각 포함). 사이트에서 사라진 프로그램은 제외
-- latitude/longitude/support_english는 trg_program_inherit_before_insert 트리거가 소속 TEMPLE 값으로 덮어씀 (여기 0/FALSE는 의미 없음, NOT NULL 통과용)
-- image_url은 templestay.com CDN(ts-cdn.com) 주소. 사진이 없는 항목은 플레이스홀더(data:image/svg+xml,... '사진 준비중')를 쓰는데, 지금은 0건.
--   외부 주소라 원본 사이트에서 프로그램이 내려가면 사진이 깨질 수 있음 - 주기적으로 재수집해서 확인할 것

INSERT INTO TEMPLE_STAY_PROGRAM (temple_id, title, program_type, image_url, description, schedule, required_items, price, duration, open_start_date, open_end_date, max_participant, support_english, latitude, longitude) VALUES
    (2, '[갑사]휴식형 템플스테이', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_10713_S.webp', '완전 자율형(휴식형) 템플스테이란 말 그대로 머무는 동안 사찰에서 필요로 하는 가장 기본적인 예절을 지키면서 자유롭게 머무는 것입니다

1. 이성끼리 같이 오시는 경우에는 각방 사용을 하셔야 합니다.

   -. 중년 가족의 경우는 실무자의 판단에 따라 결정

2. 개인 독방(1인실)을 원하시는 분들은 추가비용 2만원이 발생합니다.

   -. 입금은 예약 후 24시간 내로 해주셔야 하며 미입금시 예약 취소됩니다.

3. 참가자 개인이 자율적으로 휴식, 독서, 기도 또는 수행, 산책 등의 시간을 통해 일상에서 지친 몸과 마음을 위로하고 재충전하는 시간을 가져 보시기 바랍니다

   계룡산의 정기가 충만한 자연과 마음을 나누고, 잊고 지내던 참 나와 진지한 대화의 시간을 가져보시기 바랍니다

4. 이런분들께 완전 자율형(휴식형) 템플스테이를 권장해 드립니다.

  -. 잠시나마 혼자 조용한 곳으로 떠나고 싶으신 분

  -. 도심의 탁한 공기에서 벗어나 신선한 자연을 느끼고 싶으신 분

  -. 자아 정체성 혼란 또는 고민으로 인해 머리가 복잡하신 분

  -. 修行(수행:닦을 수 다닐 행)을 통해 몸과 마음을 건강하게 만들고 싶으신 분

  -. 그냥 아무 이유없이 갑사에 오고 싶으신 분 등등 갑사는 항상 열려 있습니다.

5. 장기간 참가를 원하시는 분들은 041-857-8921로 연락 주세요.

6. 기타 궁금 하시거나 문의가 있으시면 언제든지 연락주세요.

7. 여름철 에어컨 완비', '1일차;15:00~15:30 접수 및 방사배정;15:03~17:00 사찰안내;17:00~17:30 몸이 건강해 지는 저녁공양(자율);18:00~18:20 타종;18:20~18:50 불.법.승 삼보를 예경하는 저녁 예불(자율);19:00~21:00 나의 시간;21:00~04:00 소등 및 취침;2일차;04:00~05:00 불·법·승 삼보를 예경하는 새벽 예불(자율);05:30~06:00 몸이 건강해지는 아침공양(자율);06:00~09:30 자율정진;09:30~10:00 방사청소 및 수련복,매트커버,배게커버 반납;10:00~12:00 템플스테이 +1 프로그램 체험 가기', '1. 세면도구(수건, 치약, 칫솔, 비누 등) / 수건과 칫솔은 필참 입니다.

  ※ 개인 취향에 맞는 세면용품은 별도 지참이 가능합니다.

2. 운동화 또는 등산화(용문폭포, 천진보탑 탐방로가 산길입니다)

3. 휴대용 개인물통

4. 옷가지개인 반팔티 및 얇은 긴팔(산이라서 저녁에 약간 쌀쌀할 수 있습니다.)

