    (3, '천년의 숲, 나를 안아주는 개암사', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/6/25/20260625041145189_10_S.webp', '울금바위 아래, 천년의 평온함이 머무는 곳에서 나를 위한 진정한 휴식을 시작하세요! 복잡한 생각을 비우고, 내면의 소리에 귀 기울이는 특별한 여정, 지금 개암사에서 시작됩니다.', '1일차;15:00~16:00 도착 및 방사안내;16:00~17:00 차담 및 오리엔테이션;17:00~18:00 저녁 공양;18:00~18:30 저녁예불(자율선택);19:00~21:00 휴식 및 취침;2일차;04:00~05:00 새벽예불;07:00~08:00 아침공양;08:00~10:00 숲길 산책(자율선택);10:00~11:00 방사정리 및 소감문 작성;11:00~12:00 또 만나요!!', '두명 이상 오시는 분들은 팀별로 방사배정이 됩니다.(2인~4인) 혼자 오시는 분들은 다른 분과 함께 사용 개인 세면도구(수건포함, 삼푸, 린스), 충전기, 등산화 또는 운동화. 음식물은 냄새 안나는 간단한 간식. 개인 텀블러 준비.', 70000, '1박 2일', '2026-06-25', '2026-10-31', 20, FALSE, 0, 0),
    (4, '[당일형]  고성여행 건봉사 템플스테이 (10월~12월)', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/9/12/20260912120623088_1_S.webp', '고성여행 당일형 템플스테이 . . . .  .

