    (5, '휴식형 템플스테이, 나에게 주는 선물 (1박2일 )', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_30310_S.webp', '반복되는 일상에 지친 나에게 주는 선물~ 도심 속 힐링의 공간으로 나를 인도하여 1박 2일 동안의 새로운 경험과 소소한 행복의 추억을 만들어 봅니다.', '1일차;14:50~15:00 입소 및 방사배정;15:30~16:00 자율정진;16:00~17:00 도량안내 및 습의;17:00~17:30 저녁공양;18:00~18:30 저녁예불;18:30~21:00 자율정진;21:00~00:00 취침;2일차;05:00~05:30 새벽예불(선택);05:30~06:30 자율정진;06:30~07:00 아침공양;07:00~10:30 자유시간;10:30~11:00 방사정리 및 회향', '마스크, 수건, 세면도구, 개인물병, 운동화, 겉옷 외 개인물품. 사찰에서는 조끼와 바지만 지급합니다', 70000, '1박 2일', '2026-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (5, '경국사 체험형 템플스테이', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_30309_S.webp', '1박 2일 동안 사찰문화 체험을 통해 나를 찾아가는 특별한 체험프로그램입니다. * 만 18세 이하는 보호자의 동반이 필요합니다. * 사찰에서는 남녀 혼숙은 불가합니다. 남녀 혼숙 또는 남녀가 한방에 있는게 적발될 시 즉시 퇴실 조치됩니다. * 참가비 : 예약 후 참가일 일주일전까지 결재 바랍니다. 참가일 3일 전까지 입금하지 않을 시 강제 취소 처리됩니다. * 참가 취소시에는 취소요청을 해주셔야 다른분의 참가가 가능합니다. * 사찰 내 외부음식 반입은 금지입니다.', '1일차;14:50~15:00 입소 및 방사배정;15:30~16:30 108염주 만들기;16:30~17:00 사찰예절습의 및 타종체험;17:00~17:30 저녁공양;18:00~18:30 저녁예불;18:30~19:00 스님과의 차담;19:00~21:00 자율정진;21:00~00:00 취침;2일차;05:00~05:30 새벽예불;05:30~06:30 자율정진;06:30~07:00 아침공양;07:00~10:00 자유시간;10:00~10:30 방사정리;10:30~11:00 후기작성 및 회향', '마스크, 수건, 세면도구, 개인물병, 운동화, 겉옷 외 개인물품(북한산을 끼고 있는 사찰이라 도심보다 조금 더 춥습니다.) *사찰에서는 조끼와 바지만 지급합니다', 70000, '1박 2일', '2026-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (6, '마음숲길', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/6/27/20260627034617587_1_S.webp', '고운사 휴식형 템플스테이는 1년 365일 예불, 운력, 스님과의 차담, 천년숲길 걷기명상 등의 프로그램으로 진행됩니다. 고운사 천년숲길을 걸으면서 산사의 맑은 공기에 마음을 비우고, 본래의 맑은 나를 되찾는 소중한 시간을 가져보세요.', '1일차;15:00~15:00 사찰도착;접수;15:30~16:30 사찰안내;16:30~17:30 자유시간;17:30~18:00 저녁공양;18:30~19:10 저녁예불(선택);19:10~21:00 자유시간 및 취침;2일차;04:50~05:30 새벽예불(자율);06:00~06:30 아침공양;06:30~08:00 주지스님과의 차담;08:00~11:00 자유시간;11:00~11:00 회향', '개인 세면도구, 수건, 편한 신발(운동화,등산화 등), 개인 물병(텀블러), 상의 간편한 점퍼 및 여벌 옷(템플바지,조끼만드림)', 60000, '1박 2일', '2025-12-01', '2026-12-31', 20, FALSE, 0, 0),
    (7, '움직이는 선의 숨결! (1박2일)', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_4772_S.webp', '마음을 닦는 몸의공부, 선무도! 참된 나를 만나다. 명상, 선요가, 선기공, 선무술, 선체조 등을 포함하는 선무도 수련을 통해 몸과 마음과 호흡의 조화로움을 얻어 행복한 삶의 에너지를 되찾으세요.', '1일차;14:30 접수 및 입실안내;15:00 선무도 공연관람(월,화 없음);16:10 오리엔테이션;16:30 선무도 수련;17:40 108배;18:00 저녁공양;21:00 취침;2일차;05:00 기상;05:30 새벽예불;06:10 행선(걷기 명상);06:30 아침공양;09:00 선무도수련;10:10 사시 예불(선택);10:50 차담(5인 이상, 주말 없음);11:40 점심 공양;12:00 하산;13:10 선택프로그램:국궁(1인당 2만원)', '세면도구, 수건(위생상 대여 안함), 계절에 따른 기본 복장, 걷기 편한 신발, 물통, 계절에 따른 방한 및 방염 용품 등. 선무도 수련복(조끼,바지)/치약,세숫비누는 비치.', 120000, '1박 2일', '2017-11-12', '2026-12-31', 20, FALSE, 0, 0),
    (7, '휴식형 템플스테이! 나에게 주는 선물!', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_1745_S.webp', '천년고찰 골굴사의 마애여래 부처님의 미소 아래 힐링과 재충전의 시간을 가져보세요. 휴식형으로 선택하셔도, 다양한 체험형 템플스테이 전 일정을 자유롭게 선택하여 참여 하실 수 있습니다.', '1일차;14:30 접수 및 입실안내;15:00 선무도 공연관람(월,화 없음);16:10 오리엔테이션;16:30 선무도 수련;17:40 108배;18:00 저녁공양;21:00 취침;2일차;05:00 기상;05:30 새벽예불;06:10 행선(걷기 명상);06:30 아침공양;09:00 선무도 오전수련;10:50 스님과의 차담(5인 이상, 주말 없음);11:40 점심 공양;12:00 하산;13:10 선택 프로그램:국궁(1인당 2만원)', '세면도구, 수건(위생상 대여 안함), 계절에 따른 기본 복장, 걷기 편한 신발, 물통, 계절에 따른 방한 및 방염 용품 등. 선무도 수련복(조끼,바지)/치약,세숫비누는 비치.', 120000, '1박 2일', '2025-04-15', '2026-12-31', 20, FALSE, 0, 0),
    (7, '나를 위한 하루동안의 행복여행!', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_2710_S.webp', '골굴사의 트레이드 마크인 ''선무도 수련 체험''과 ''선무도 공연 관람(무료)'' 신라 화랑의 기상을 계승한 체험형 프로그램인 ''국궁'' 등의 다양한 프로그램을 즐기실 수 있습니다. 관공서와 기업의 연수, 학교의 수학여행과 체험학습, 각종 단체나 동호회의 체험 프로그램으로 인기가 많은 당일형 템플스테이입니다.


