    (8, '한 번쯤 템플, 도심 속 오아시스를 찾아.....', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/7/28/20260728050130930_2_S.webp', '자연의 변화를 온몸으로 체감하며 도심속 사찰에서 내면의 나와 마주하는 특별한 시간입니다. 잠시 일상을 멈추고, 고요한 사찰에서 사찰음식도 체험하고 비움의 시간을 가져 보세요.', '1일차;15:00~15:30 수련복 지급 및  방배정;15:30~16:00 오리엔테이션 & 사찰 안내;16:00~17:30 북 명상 & 숲길 내려놓기 명상;17:30~18:00 제철재료로 만든  저녁공양;18:00~18:30 저녁예불;18:30~19:30 자유시간;19:30~21:00 스님과의 차담& 대보탑 탑돌이 소원빌기 (택1);21:00~03:00 취침;2일차;03:00~03:30 새벽 예불(자율참여);07:00~08:00 아침공양;08:00~09:00 자유시간;09:00~09:30 나를 만나는 시간(108배);09:30~10:30 후기작성 회향', '수건, 세면도구, 조끼에 받쳐입을 상의, 여벌옷, 운동화,양말, 개인물통(정수기이용). 네이비색 조끼에 받쳐 입을 흰색 티셔츠 착용 바랍니다. 반바지, 민소매, 맨발은 안돼요.', 80000, '1박 2일', '2026-06-25', '2026-11-02', 20, FALSE, 0, 0),
    (8, '잠깐 멈춤! 일상에서 벗어나 나를 찾다', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/8/25/20260825050426847_3_S.webp', '지친 일상을 벗어나 서울근교에서 즐기는 휴식의 시간, 혼자 있어야 진정한 나를 찾을 수 있습니다. 우면산 푸른 숲을 천천히 걸으며 심신 안정을 찾고, 밤에는 별을 보며 잠시 일상을 멈추는 시간입니다.', '1일차;15:00~15:30 접수 및 방배정;15:30~16:00 사찰투어;16:00~17:30 명상;내면의 나를 만나는 시간;17:30~18:00 저녁공양;18:00~18:50 저녁예불;18:50~20:00 다도체험;스님과의차담;20:00~21:00 자유시간;2일차;03:00~03:30 새벽예불(자율);07:00~08:00 아침 공양;08:00~09:00 자유시간;09:00~09:30 영혼을  깨우는 시간 108배;09:30~10:30 커피& 티, 참가후기 작성;회향', '수건(꼭), 세면용품, 조끼에 받쳐 입을 흰색 티셔츠, 양말 착용, 여벌옷, 운동화(편한 신발), 개인 물통(정수기 이용). 비누 드라이기 등은 비치되어 있습니다', 80000, '1박 2일', '2025-06-15', '2026-11-01', 20, FALSE, 0, 0),
