한라산 기슭 해발 660m에 자리 잡고 있는 제주 관음사는

인체 리듬을 활성화시키는 고도에 위치해 있어, 숨을 쉬는 것만으로도 생명력을 되찾는 느낌을 받을 수 있습니다.

또한, 아름다운 한라산을 걷다 보면 예상치 못하게 귀여운 노루를 만나는 기쁨도 누릴 수 있습니다.

세상의 모든 소음으로부터 멀리 벗어나, 온전히 나 자신에게 집중할 수 있는 이곳은

가슴을 탁 틔워 주고 자연스레 마음의 짐을 내려놓게 만들어 줍니다.

아무것도 하지 않아도 마음 한구석 불안함이나 허전함 없이, 온전히 평온을 느낄 수 있는 이곳의 매력을 느껴보세요.

