참가자 개개인이 자율적으로 휴식, 독서, 기도, 산책, 트래킹 등을 하며 일상에서의 피로를 풀며 자유롭게 머무는 것입니다.

마이산의 기운이 가득한 금당사에서 자연을 만끽하며 잊고 지내던 나와 만나는 시간을 가져보시기 바랍니다.

*유의사항

一 사찰에서의 기본예절은 지켜주셔야 하며, 사찰안내를 제외하고  자유로운 휴식과 포행을 하시면 됩니다

一 프로그램은 사찰 사정에 따라 내용이 일부 변경될 수 있습니다.

一 공양 시간을 반드시 지켜주셔야 하며, 공양 안 하실분은 최소 1시간 전에 담당자에게 연락해주셔야 합니다.

*이런 분들께 소확행 템플스테이를 권장해 드립니다.

1. 무언가에 얽매이지 않고 휴식을 취하고 싶으신 분

2. 잠시나마 조용한 곳으로 떠나고 싶으신 분

3. 도심의 탁한 공기에서 벗어나 신선한 자연을 느끼고 싶으신 분

4. 자기 수행을 통해 몸과 마음을 건강하게 만들고 싶으신 분

5. 아무 이유없이 마이산 금당사에 오고 싶으신 분 등

＊가족이 신청시 같은방에 배정됩니다.

＊동참자와 다른 방 사용을 원하실 경우 미리 연락주셔야 합니다. 별다른 연락 없으실 경우, 자동으로 같은 방에 배정됩니다.

