정회원은 [회원전용] 프로그램을 선택하여 예약해주십시요.

  ☞ 정회원 가입하러가기 ☜

잘 쉬려면 먼저 멈추어야 합니다. 그래야 쉼이 가능합니다. 내소사는 천년고찰로 자연 그대로가 쉴 수 있는 곳 입니다. 봄에는 벚꽃들, 여름에는 노란 상사화, 가을에는 곱게 물든 단풍나무, 겨울에는 눈부신 설경등등 또한 국보와 보물 문화재가 가득한 곳입니다. 특히 아름다운 길 100선에 들어가 있는 500여미터 펼쳐진 전나무는 그냥 보고 걷기만해도 저절로 힐링이 되는 그러한 곳입니다. 내소사 템플스테이에 오시는 분들이 지내면서 저절로 쉼이 되었으면 좋겠습니다.

프로그램

* 새벽예불은 필수 참석으로 변경되었습니다.

새벽예불은 고요한 새벽에 부처님께 예경드리고, 스스로를 돌아보는 귀한 시간입니다.

조금 이른 시간이지만, 이번 템플스테이를 더 깊이있게 경험하는 시간이 될 것입니다. 함께 해주시기를 부탁드립니다.

* 전나무숲걷기 - 전나무향이 그윽한 숲길을 걸으며 땅의 촉촉함을 느껴봅니다.

* 사찰음식체험 - 육류와 오신채가 안들어간 건강한 채식 식단을 경험.

* 사찰안내 - 사찰을 돌면서 자세한 설명과 재미난 이야기 듣기.

* 종소리 듣기 - 저녁, 새벽예불 전에 치는 종소리에 그냥 멍 때려봅니다.

* 스님과 차담(목, 금 운영) - 차를 마시며 나를 행복하고 자유롭게 하는 이야기를 듣고 사찰과 수행에 대해서 궁금한것들 질문하기.

* 선택형 체험 프로그램(연꽃만들기 5천원, 키링만들기 5천원, 108염주만들기 1만원, 금강경사경 1만원, 고무신 단청 그리기(예약 필수) 2만원)

예약안내

*최소 1박2일에서 최대 6박7일까지 예약가능합니다.

*참가자분께서 [예약신청]을 하시면 입금계좌 문자가 자동으로 발송됩니다.

*받으신 계좌번호로 참가비를 입금 해주시면 됩니다.

*[예약신청]만 하고 입금이 안 되면 [예약완료]가 되지 않습니다.

*[예약신청] 후 3일 내 입금이 되지 않으면 예약은 자동 취소될 수 있습니다.

* 두명 이상 오시는 분들은 팀별로 방사배정이 됩니다. (2인~4인)

* 방사 운영 상황에 따라 일행이 아닌 다른 동성 참가자와 같은 방을 사용하실 수 있으며, 방사는 임의로 배정됩니다.

* 독방 신청을 하시지 않으셨을 경우 다른 분들과 같은 방을 사용하실 수도 있습니다.

* 혼자 오시는 분들은 다른 분과 함께 사용하거나, 추가요금을 내고 독방을 사용할수 있습니다.

* 예약시 독방 사용요금 선택 : 3만원 추가 / 독방 옵션은 방사 갯수 외의 일수나 인원수에 영향을 받지 않습니다. 예) 2박 3일 2인 기준 : 총 31만원(28만+3만)

* 신청 후 입금순으로 방사배정이 되니, 예약 후 바로 입금 바랍니다.

* 미성년자만 참여할 경우, 부모님 동의서는 필수이고 고등학생 이상 가능합니다.

