    (28, '자연과 나 - 편백숲과 함께하는 템플스테이', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_25079_S.webp', '창원편백치유의숲 센터와 함께하는 템플스테이. 예불, 타종체험 등 사찰 문화와 함께 편백치유의숲 센터에서 인바디측정, 편백숲체험, 숲명상, 족욕, 방향제만들기 등 체험. 편백숲체험 프로그램은 고등학생 이상 참여 가능(미취학·초등·중등 참여 불가).', '1일차;11:00-12:00 입소 및 방사안내;12:00-12:30 점심공양;13:30-14:00 사찰안내;14:00-16:30 창원편백치유의 숲 체험;16:30-17:00 저녁공양;18:20-18:40 타종체험 및 저녁예불;18:50-00:00 자유시간 및 취침;2일차;00:00-04:30 기상;05:00-05:30 새벽예불(자율);06:30-07:10 아침공양;08:00-09:30 자유시간 및 단주만들기(자율);10:00-12:00 소감문 작성 및 집으로', '수건 및 세면도구(샴푸 등), 텀블러(정수기사용), 여벌옷, 가벼운 외투', 70000, '1박 2일', '2025-12-24', '2026-12-31', 20, FALSE, 0, 0),
    (28, '2026년 찾아가는 템플스테이 - 세화여고 파라미타', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/1/8/20260108100251180_1_S.webp', '-"찾아가는 템플스테이"-세화여고(파라미타)-
