    (28, '[휴식형] 고요한 마음', '휴식형', 'https://ts-cdn.com/ups/templePrg/2025/3/26/20250326050308690_1_S.webp', '지친 일상에서 벗어나 산사의 일상을 체험하면서 자유롭게 일정에서 벗어나 편안하게 쉬어가는 템플스테이를 경험해 보세요. 과감하게 일상에서 벗어나 여유 가득한 하루가 되길 바랍니다.

- 고등학생 미만 미성년자는 보호자 동반없이 참여하실 수 없습니다. 만약 미성년자만 예약되는 경우 통보없이 예약취소됨을 알려드립니다.

- 고등학생만 참가하는 경우 예약사항에 보호자 이름, 연락처를 기재하시기 바랍니다.

- 방사는 1팀 1실입니다. 휴심당은 1팀당 2인까지 가능. 3인  이상인 경우 본관 방사 제공: 시설안내 2페이지에 본관방사, 3~4페이지는 휴심당 방사 사진이 있으니 참고

- 예약인원은 다 차지 않았어도 방사 배치 완료로 인해 추후 예약이 취소될 수도 있습니다. 양해 부탁드립니다.

- 예약 후 3일까지 참가비를 입금하지 않으실 경우 자동예약취소됩니다. 입금 후 다음날까지 예약완료 알림톡 또는 템플담당자 전화를 못받으셨을 경우 꼭 확인전화 부탁드립니다.(전화상담 오전 9시~오후 5시)

- 예약일 3일전까지 100% 환불입니다. 홈페이지를 통해 예약취소를 해주셔야 하며 예약일 2일~당일 취소는 환불불가입니다.

- 법복제공합니다.

-> 봄,가을,겨울 : 조끼, 법복바지

-> 여름(낮기온 25도 이상 시) : 법복바지만 제공 : 티셔츠 및 윗옷은 제공하지 않으니 꼭 옷을 챙겨오십시오.

- 올해 추석 연휴동안(9/24 ~ 9/27) 템플스테이를 운영하지 않습니다.

- 9월 8일자로 10월 예약 오픈되었습니다.

- 11월달은 템플스테이 행사 관계로 10월 중순쯤 다른 프로그램으로 예약오픈됩니다.

-4월 1일부터 타종체험 및 저녁예불 체험 시간이 변경됩니다 (18:20 ~ 18:50)

- 원활한 안전 관리와 보험 적용을 위해 모든 예약은 실명으로 이루어져야 합니다. 타인 명의 도용 등 허위 정보로 예약된 경우, 당 사찰은 시설 관리권에 의거하여 별도의 통보 없이 예약 취소 및 현장 퇴방 조치를 시행할 수 있습니다.', '1일차;15:00~15:20 입소 및 방사안내;15:30~16:00 사찰안내;17:00~17:30 저녁공양;17:00~17:50 자유시간;18:20~19:00 타종체험 및 저녁예불;19:00~00:00 자유시간 및 취침;2일차;05:00~05:30 새벽예불(자율);05:30~06:30 휴식시간;06:20~07:00 아침공양;07:00~10:00 자율포행 및 방사정리, 소감문 작성;10:00~10:30 퇴실', '1. 수건 및 세면도구(샴푸 등) 2. 여벌옷 3. 개인의약품 4. 가벼운 외투 5. 텀블러', 50000, '1박 2일', '2025-12-01', '2026-12-31', 20, FALSE, 0, 0),
