    (29, '사불산(四佛山)... 옛길을 걷다', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_27337_S.webp', '해발 600고지의 대자연을 품고 있는 대승사에서 스님들의 일상을 같이 체험하며, 스님과의 차담, 예불, 윤필암, 묘적암,사면석불 포행과 쉼이 있는 프로그램으로 참가자들이 자율적으로 몸과 마음의 휴식을 취하는 프로그램입니다. 일년 365일 언제나 가능하며, 최대 기간은 4박 5일이며, 추가 연장도 가능합니다. 예약안내 방사 준비등의 이유로 예약은 참가 3일전에 예약을 받습니다. 프로그램안내 프로그램은 사찰안내 예불 스님 차담은 자율적으로 참여 할 수 있으며, 사찰 내 일정으로 프로그램 일정 변경 취소될수 있습니다.', '1일차;15:00~15:30 사찰도착 및 방사배정;16:00~16:30 사찰안내 및 오리엔테이션;17:00~17:30 저녁공양;18:50~18:55 저녁타종 및 사물관람(자율);19:00~19:20 저녁예불(자율);21:00~21:30 취침준비 및 취침;2일차;04:00~04:30 도량석 및 새벽예불(자율);06:10~06:30 아침공양;08:30~10:30 암자순례 및 명상(자율);10:40~11:00 소감문작성 및 방사 정리정돈;11:10~11:30 회향', '개인 세면도구(수건, 칫솔), 여벌 옷(외투), 운동화(편한 신발), 양말, 개인(보온) 물병 *겨울 참가시 : 방한용품 및 아이젠 등', 60000, '1박 2일', '2017-01-01', '2026-12-31', 20, FALSE, 0, 0),
