    (30, '[체험형] "고요한 숨결, 마음의 쉼"', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/7/14/20250714043516988_1_S.webp', '복잡한 일상에서 벗어나 고요한 산사에서 진짜 ''나''를 마주하는 명상 프로그램. 숲길 걷기, 호흡 집중, 좌선/걷기 명상, 스님과의 차담 등 진행.', '1일차;15:00-15:30 도착, 방사배정, 체험복지급;16:00-16:50 사찰예절교육, 사찰안내;17:00-17:30 저녁공양;17:50-18:10 타종체험(소리명상);18:10-18:30 저녁예불(자율);19:30-20:00 좌선명상;21:00-00:00 취침;2일차;05:00-05:30 새벽예불(자율);06:30-07:00 아침공양;07:00-08:00 걷기명상, 좌선명상(자율);08:00-09:00 스님과의 차담;09:00-10:00 흔적지우기, 집으로', '티셔츠, 개인물통, 개인 세면도구(수건,치약,칫솔,샴푸,비누), 드라이기, 양말, 운동화, 여벌 옷 등', 90000, '1박 2일', '2026-06-01', '2026-12-31', 20, FALSE, 0, 0),
    (30, '[당일형] 행복한 산사의 하루', '당일형', 'https://ts-cdn.com/ups/templePrg/2025/3/30/20250330102404679_1_S.webp', '친환경적인 공간속에서 대자연과 교감하며 자연과 하나가 되는 여행.
자신의 내면을 성찰하고, 무거운 마음의 짐을 비우는 평화로운 휴식여행.
사찰음식, 연등만들기, 단주만들기 등 불교의 전통문화를 직접 즐기는 체험여행.
