자연 속에 자리한 백제고찰 대원사.

고요한 산사의 품 안에서

참된 나를 마주하는 휴식과 깨달음의 여정이 시작됩니다.

대원사 템플스테이는

산사에서 1박 2일 이상 머물며,

다양한 체험과 명상을 통해

몸과 마음의 조화를 되찾는 프로그램입니다.

보성의 향기로운 차와 함께

삶의 속도를 잠시 늦추고,

내면의 평화를 회복하는 시간을 가져보세요.

○ 당일 예약을 원하시는 분께서는 유선 연락 바랍니다.

