    (31, '[휴식형]쉼의 길 위에서, 나를 만나다', '휴식형', 'https://ts-cdn.com/ups/templePrg/2025/4/15/20250415042513686_1_S.webp', '천봉산 깊은 곳, 쉼이 머무는 자리 &ndash; 대원사 휴식형 템플스테이

“잠시 멈추면 비로소 들리는 것들이 있습니다.”

전라남도 보성, 천봉산 자락의 깊은 산속에 자리한 대원사.

맑은 계곡물과 고요한 숲, 그리고 깨끗한 공기가 어우러진 이곳은

마음의 짐을 내려놓고 고요히 머물기에 더없이 좋은 곳입니다.

대원사의 휴식형 템플스테이는

정해진 일정 없이, 오롯이 나에게 집중하는 시간을 선사합니다.

자연의 소리에 귀 기울이며 걷다 보면

복잡한 생각은 잠잠해지고,

단순하고 평온한 마음이 다시 나를 채웁니다.

이곳에서는 역할도, 시선도, 비교도 없습니다.

그저 ‘나’로 존재하는 시간.

삶의 속도를 잠시 늦추고,

자연의 호흡과 나의 숨이 다시 만나는 자리 &mdash;

대원사에서 본래의 나와 마주하는 치유의 여정을 시작하세요.

○ 당일 예약을 원하시는 분께서는 유선 연락 바랍니다.

