    (41, '전통 메주 만들기 체험', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_25527_S.webp', '2026년 10월 31일 (토) 오전 10시 깊은 산속 망경산사에서 전통 사찰음식의 핵심인 메주를 직접 만들어보는 특별한 체험을 제공합니다.
