    (48, '바보여행 - 지리산에서 하룻밤, 그저 바라보는 여행자로 살아보기', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_10635_S.webp', '나는 바보행자입니다. 우리는 늘 생각을 만들어내고 과거와 미래를 오가며 분별망상을 만들어 냅니다. 무언가를 있는 그대로 보는 것이 진실된 수행의 목적입니다. 지리산 문수암에서 하룻밤, 그저 바라보는 수행자로 살아보는 프로그램.', '1일차;15:00~16:00 도착_방사배정_오리엔테이션;16:00~17:00 스님과의 첫만남;17:00~17:30 저녁공양;17:30~18:30 휴식;18:30~19:30 저녁예불;19:30~21:00 나를 찾아가는 108배 명상;21:00~00:00 취침;2일차;05:30~06:00 새벽예불(자율);07:00~07:30 아침공양;07:30~07:50 휴식;08:00~10:30 바보숲길 걷기명상;10:30~11:00 소감문 및 운력(방청소);11:00~11:30 점심공양;11:30~12:00 스님과의 차담후 회향', '세면도구(치약, 칫솔, 수건 등), 간편화(산행용 편한신발), 개인 물병, 우산(우비), 양말 등.', 80000, '1박 2일', '2025-04-30', '2026-12-01', 20, FALSE, 0, 0),
    (48, '바보여행(바라보기여행)', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/3/10/20250310073329856_1_S.webp', '우리 생에서 가장 먼 여행은 머리에서 가슴까지의 여행이라고 합니다. 모든 것을 분별없이 받아들일 수 있는 낮은 곳으로의 여정으로 초대하는 바보여행 프로그램.', '1일차;15:00~15:30 도착, 숙소안내;15:30~16:00 오리엔테이션;16:00~16:50 스님과의 첫만남;17:00~17:30 저녁공양;18:30~19:30 저녁예불 & 108배;19:30~20:00 참선 및 명상;21:00~00:00 취침;2일차;05:00~05:30 새벽예불;07:00~07:30 아침공양;07:30~08:00 휴식;08:00~10:30 바보숲길 걷기명상;10:30~11:00 방정리 및 아름다운 마무리;11:00~11:30 점심공양;11:30~12:00 스님과의 차담 및 회향', '세면도구(치약, 칫솔, 수건 등), 간편화(산행용 편한신발), 개인 물병, 우산(우비), 양말 등. 동절기 따뜻한 의류.', 80000, '1박 2일', '2025-04-30', '2026-12-01', 20, FALSE, 0, 0),
    (48, '마음을 채우는 발우공양', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/9/11/20260911031129709_1_S.webp', '바쁜 일상을 살아가다 보면 온전히 ‘나 자신’을 바라보는 시간은 좀처럼 갖기 어렵습니다.

문수암에서는 ‘바라보기’를 이야기합니다.

바라본다는 것은 단순히 눈으로 보는 것이 아니라, 잠시 멈춰 지금의 나와 주변의 모습을 있는 그대로 들여다보는 일입니다.

발우공양 역시 그렇게 나를 바라보는 시간입니다.

‘발우’는 스님들이 사용하는 그릇을, ‘공양’은 음식을 먹는 것을 넘어 공경과 감사의 마음으로 음식을 대하는 것을 의미합니다.

처음 발우공양을 마주하면 조금 낯설고 어색할 수 있습니다.

말없이 음식을 마주하고, 숟가락 하나, 젓가락 하나를 움직이는 순간에도 온전히 마음을 기울여야 하기 때문입니다.

하지만 고요한 식사 속에서 우리는 조금씩 바라보기 시작합니다.

*1인 방사비용은 140,000원 입니다. 꼭!! 확인 후 예약 부탁드립니다.

**주말 예약은 조기에 마감되는 경우가 많습니다. 예약 전 일정을 충분히 확인하신 후 신중하게 신청해 주시기 바랍니다.

   (주말 환불 문의는 1주일 전 문의주셔야 합니다)

***법당 출입시 양말 착용 필수입니다.

*날씨, 사찰 상황에 따라 체험은 변경 또는 취소될 수 있습니다.

*예약 순 마감이 아닌 입금 순 마감입니다.

*예약자와 입금자명 상이할 경우 예약 확인이 어렵습니다. 연락주시기 바랍니다.

*사찰 방사 사정에 따라 다른 참가자분들과 같은 방사 사용할 수 있습니다.

*오리엔테이션은 필참입니다. 시간 맞춰서 오시기 바랍니다

*3시부터 입실 가능합니다(이전 도착시 차실에서 대기 후 순차적으로 안내도와드립니다)

업무 시간 : 9시~17시 (그 외 시간은 문자 남겨주시면 순차적으로 연락드립니다)

