* 입금순으로 접수 완료 됩니다. 부득이하게 방사 부족으로 승인불가가 될 수가 있습니다.

* 기본요금제 1인은 방을 다른분과 같이 쓸수도 있습니다.

* 1인실 사용을 원하시는분은 추가요금(2만원) 있습니다.  참가자 요청 사항란에 "V"표시하시면 됩니다.

* 2인이상은 일행끼리 방을 쓸수 있습니다.

