    (54, '2026년 제93회 마음 하나 템플스테이', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/2/28/20250228092837581_1_S.webp', '마음 하나

그 옛날 천하장수가

천하를 다 들었다 다 놓아도

한 티끌 겨자씨보다

어쩌면 더 작을

그 마음 하나는 끝내 들지도 놓지도 못했다더라

설악 무산 조오현 한글 선時

마음이 만물의 근원이라는 유심(唯心)

마음을 일으키면 발심(發心)이고

마음을 잡으면 조심(操心)이 되며

마음을 풀어 놓으면 방심(放心)입니다.

마음이 끌리면 관심(觀心)이고

마음을 편안케 하면 안심(安心)이며

마음을 일체 비우면 무심(無心)입니다.

처음 먹은 마음은 초심(初心)이고

늘 지니고 있는 떳떳한 마음이 항심(恒心)이며

우러나오는 정성스러운 마음은 단심(丹心)입니다.

작은 일에도 챙기면 세심(細心)이고

사사로움이 없으면 공심(公心)이며

꾸밈이나 거짓이 없는 참마음이 본심(本心)입니다.

욕망의 탐심(貪心)과 흑심(黑心)을 멀리하고

어지러운 난심(亂心)과 어리석은 치심(癡心)을 버리고

애태우는 고심(苦心)을 내려 놓으면 하심(下心)입니다.

아아아아 내 안에 파도 같은 많은 생각과 마음(心)이 존재한다는 사실

그것을 확인하는것이 백담사 템플스테이입니다...

* 마음 하나 템플스테이는 1박 2일 프로그램으로 체험과 휴식을 동시에 할 수있는 백담사의 작은 선물입니다..

