    (57, '{선명상} 참사람 가행정진 템플스테이 - 다인실', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/1/24/20260124063229472_1_S.webp', '"마음 속 부처를 찾아낸 대자유인이 ''참사람''입니다." 욕망은 인간의 자연적 본성에 속한 것으로 그 자체를 문제삼을 수는 없다. 허나 근원적 위치에서 작용해야 한다. 모든 사람은 본래로 참사람이다. 이는 횡적 넓이의 평등이라 할 수 있고, 종적 깊이의 내용적 평등이라 하는 불교의 평등원칙이다. 선명상 참사람 가행정진 템플스테이는 서옹스님의 ''참사람'' 정신을 바탕으로 선명상의 활성화를 위해 시도하는 프로그램입니다. 동참큰스님의 임제록 강의와 실참(정진)을 중심으로 1박 2일 동안 선명상의 진수를 체험하는 시간입니다. 또한 비자림 숲과 백양사 부근 숲길을 걸으며 서옹스님의 "참사람"의 의미를 되새길 수 있는 시간입니다.', '1일차;14:00~15:00 입실 및 수련복 갈아입기;16:00~17:00 오리엔테이션 사찰안내;17:10~18:00 저녁공양;18:00~18:30 타종체험 (자율);20:00~20:50 임제록 선강;21:00~22:00 입선;22:00~22:10 행선;22:10~23:00 좌선;23:00~23:10 행선;23:10~00:00 좌선;2일차;00:00~00:10 행선;00:10~01:00 좌선;01:00~04:00 방선, 취침;04:00~04:20 기상;04:30~05:00 새벽예불;06:15~06:50 아침공양;07:00~08:30 자율 산행;08:30~08:30 침구류 반납;10:00~10:30 템플복 반납 및 방사정리;10:30~11:00 퇴실', '수건, 개인 세면도구(치약과 비누만 제공), 헤어드라이기 .개인물병(꼭 지참), 운동화, 모자, 양말(법당출입시 양말 착용) . 조끼 안에 입으실 티셔츠 준비(수련복 바지와 조끼가 제공됩니다.) .상비약 *겨울에는 내복(타이즈)과 겉옷을 꼭 챙겨오세요.', 90000, '1박 2일', '2025-12-27', '2026-12-31', 20, FALSE, 0, 0),
