    (59, '쉼, 템플스테이 - 휴식형', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_19330_S.webp', '복잡한 도시를 벗어나서, 오롯이 나만의 시간을 가질 수 있는 휴식형 프로그램입니다. 머무시는 동안 바람소리,새소리, 자연이 주는 편안하고 맑은 기운으로 재충전할 수 있는 소중한 시간을 가져보시기 바랍니다.

*다른 참가자들 포함해서 전체 인원이 최소 참가 인원 5인 미만 인 경우 프로그램 진행이 취소됩니다. (최소인원 미달 시 늦어도 3일전에는 프로그램 취소 연락 드립니다.) 또는 사중 행사로 인해 프로그램 진행이 어려울 경우에도 사전에 취소 연락드립니다.

*방사는 남.여를 구분하여 2~3인 작은방 1실 또는 예약인원이 많을 경우 4인~8인 큰방 1실 사용 기준입니다. 남.여 혼숙은 불가하나 2~3인 가족단위 입실시는 남.여 구분없이 작은방 1실로 배정해드립니다. 예약시 요청사항에 내용 기재 바랍니다.

*1인실 개인방사 사용요청시는 개인방사 사용료 1박당 20,000원 추가됩니다. 메모란에 1인실 개인방사 신청 기입해주시고 개인방사비 추가해서 입금바랍니다.

*참가기간은 최대 2박 3일까지 가능하며 2박3일 참가자에게는 2일째 점심공양도 제공됩니다. 장기 숙박은 접수받지 않습니다.

*계좌이체시는 예약후 1일 이내 참가비를 입금하여 주시기 바랍니다. 입금 확인후 예약완료 처리 됩니다. 1일내 참가비 미입금시 예약은 자동 취소됩니다.

*초등생, 중학생은 단독 참가가 안되며 부모님과 동반시 참가 가능합니다. 고등학생은 보호자 동의서(보호자 연락처 필수)가 있으면 단독 참가 가능합니다, 만 5세 이상부터 참가 가능합니다.

*프로그램 일정을 준수하기 위하여 2시전까지 입실 바랍니다. 당일 예약은 받지 않습니다..

*템플스테이 체험권 사용하실분은 예약화면 체험권 사용란에 체험권 등록번호 16자리 기재해주시고 입실 당일날 체험권 원본 제출바랍니다. 체험권 사용시 등록번호 미기재 에약건은 예약 접수하지 않습니다.

*사찰 내부사정에 따라 선명상 프로그램 진행이 어려울 경우에는 염주 만들기 체험 또는 부채 채색 하기 프로그램으로 대체 될수 있습니다.

*(중요사항) 범어사 템플스테이관은 범어사 경내로 부터 800미터 떨어진, 걸어서 20분 거리의 선문화교육센터에 있습니다. 오시는길 반드시 확인후 입실 바랍니다.

*수요일~일요일 주5일 근무로 월요일~화요일은 휴무 입니다.

 그리고 월~화 휴무일은 전화 통화가 되지 않으니 문의 사항은 휴대폰 문자(010-2581-5726) 또는 이메일(beomeosa@templestay.com)으로 남겨주시면 답변 드릴수 있도록 하겠습니다.

