하루의 쉼표

용인 문수산 법륜사의 당일형 템플스테이는 짧은 시간 동안 핵심적인 불교 사찰 문화를 체험하고 마음을 정화할 수 있는 힐링 프로그램입니다.
1박 2일이 부담스러운 당신을 위해 준비한 법륜사의 특별한 선물!
맑은 공기 가득한 문수산 자락에서 건강한 사찰요리를 맛보고, 잠시 일상의 속도를 늦추고, 오롯이 나를 만나는 시간이 될 것입니다.

