진정한 휴식은 마음의 쉼에서 시작됩니다

서울에서 단 1시간, 숲의 고요함이 머무는 곳에 보덕관음사가 있습니다. 제때 정성 어린 공양(식사)을 하고,

은은한 종소리에 맞춰 예불을 드리고 사찰마당에 앉을수도 누울수도 떠오르는 복잡한 생각은 잠시 내려놓으세요.

누구도 강요하지 않는 온전한 나만의 시간. 자연의 품에서 깊은 마음의 쉼을 경험해 보세요.

보덕관음사에서 준비한 빈백에서 누워 별과달과 친구처럼 편안하게 쉬어보세요~

* 예약 후 자동문자를 받으시더라도, 참가비 입금이 완료되어야 최종 예약완료가 됩니다.

* 환불송금은 수수료를 제외한 금액을 환불해드립니다.

	휴식형 운영 : 상시 운영(1박2일부터 최대 7일까지 예약 가능)
	방사(숙소) 사용 : 템플스테이의 방사는 공동체 생활을 통한 수행의 연장으로, 다른 참가자분들과 함께 사용하는 것을 원칙으로 하고 있습니다
	단체 예약 : 8인 이상 단체의 경우 일정 협의 후 맞춤형 프로그램 가능

👍 휴식형 템플스테이만의 특별한 혜택

	자율성 : 프로그램은 자율 참석
	편의 제공 : 수련복 지급 및 주차장 무료 이용

