    (74, '석굴암 천년의 숨결', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/12/1/20251201092136541_1_S.webp', '자랑스런 세계문화유산 석굴암에서 새벽예불을 보는 특별템플스테이입니다. 석굴암 새벽예불은 특별프로그램으로 체험권을 사용하실 수 없습니다. *** 예약 후 7일 이내에 미입금시 취소될 수 있으며, 예약후 인원이 추가되시거나 지인이신데 따로 예약하신 분들은 방배치시 참고할 수 있게 미리 문자나 예약시 메모해 주시기 바랍니다 . ***단체는 프로그램은  사전협의 가능합니다 *** 사찰사정에 따라 프로그램이 일부 변동될 수 있으며, 불국사 템플관은 불국사 경내에 위치하고 있지 않고 차량으로 5분 거리에 있음을 인지하시기 바랍니다***

