** 원활한 안전 관리와 보험 적용을 위해 모든 예약은 실명으로 이루어져야 합니다. 타인 명의 도용등 허위 정보로 예약된 경우, 당 사찰의 시설 관리권에 의거하여 별도의 통보없이 예약취소 및 현장 퇴방 조치를 시행할 수 있습니다', '1일차;14:30~15:00 도착 및 방사안내;15:00~15:30 사찰예절;15:30~18:00 사찰투어 또는 숲속포행;18:00~18:30 저녁공양;18:40~19:00 사물소리명상;19:00~19:20 예불(禮佛);19:20~20:20 선(禪) 명상;20:20~20:30 탑돌이 및 3분 명상;20:30~21:00 세면 및 취침준비;21:00~03:00 취침;2일차;03:00~04:00 기상 및 석굴암으로 이동;04:00~05:30 석굴암 새벽예불;05:30~06:30 아침공양;06:30~08:30 나만을 위한 쉼;08:30~09:30 스님과의 차담;09:30~10:00 소감문 작성 및 회향', '개인 세면도구(수건, 칫솔) 여벌옷(외투), 운동화(편한 신발), 양말, 개인(보온) 물통

