    (75, '비자나무 숲길 아래서...', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_26971_S.webp', '불회사는 1천 7백년 전에 인도 마라난타 스님께서 나주 영산강을 통해 차씨와 부처님을 모시고 오셔서 창건했다는 스토리가 전해지는 사찰로 넓은 야생차밭을 보유하고 있으며 도량을 감싸고 있는 비자나무 숲은 국가 산림문화유산으로 지정되어 있습니다. 비로약차는 비자나무 아래서 이슬을 머금고 자란 찻잎을 불회사 스님들이 직접 만드십니다. 비로약차를 마시고, 비자나무 아래와 동백 숲길에서 걷기 명상을 통해 일상에서 지친 몸과 마음을 치유하시는 시간을 가지시길 바랍니다.', '1일차;15:00~15:30 사찰도착 및 접수;15:30~16:10 오리엔테이션 및 사찰안내;17:30~18:00 저녁공양;18:30~19:00 저녁예불(자율) 체험;21:00~21:30 취침준비 및 취침;2일차;04:30~05:10 새벽예불;07:00~07:30 아침공양;08:00~10:00 비자나무 숲길 걷기명상(자율);11:00~11:30 소감문 작성 및 방사 청소 후 퇴실', '개인 세면도구, 수건, 칫솔, 여벌옷, 운동화(편한 신발), 양말, 개인물병 (동절기에는 개인 방한용품 준비)', 60000, '1박 2일', '2025-03-04', '2027-12-31', 20, FALSE, 0, 0),
    (75, '주지스님과 함께 하는 숲체험 및 비로약차 다례체험', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_28068_S.webp', '불회사는 1천 7백년 전에 인도 마라난타 스님께서 나주 영산강을 통해 차씨와 부처님을 모시고 오셔서 창건했다는 스토리가 전해지는 사찰로 넓은 야생차밭을 보유하고 있습니다. 그리고 도량을 감싸고 있는 비자나무 숲은 국가 산림문화유산으로 지정되어 있습니다. 비로약차는 비자나무 아래서 이슬을 머금고 자란 찻잎을 불회사 스님들이 직접 만드십니다. 비로약차를 마시고, 비자나무 아래와 동백 숲길에서 걷기 명상을 통해 일상에서 지친 몸과 마음을 치유하시는 시간을 가지시길 바랍니다. ■ 예약 및 입금 안내 ▷ 참여인원은 10명~40명까지 신청 가능합니다.(문의 : 061-337-3440) ▷ 예약 신청 후 입금(결제)까지 완료하셔야 예약이 완료되며, 예약완료 문자를 발송해 드립니다. ▷ 날짜 변경: 예약완료 이후, 날짜 변경은 1회 가능하며, 날짜 변경 후 취소 시 환불 불가합니다. ■ 프로그램 일정은 사찰의 사정에 따라 변경될 수 있습니다.', '1일차;14:00~14:50 숲체험;14:50~15:00 휴식;15:00~16:00 다례체험', '간소한 복장', 10000, '당일', '2024-11-17', '2027-12-31', 20, FALSE, 0, 0),
    (76, '붓다숲 명상(1박2일)', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/6/14/20260614073153758_4_S.webp', '언제나 열려 있는, 지금 여기서 행복한 템플스테이. 하루를 정신없이 보내다 보면 ''나''는 점점 뒤로 밀려날 때가 있습니다. 가끔은 잠시 멈춰서 조용히 마음을 들여다보는 시간도 필요합니다. 디지털 디톡스와 묵언을 통해 자신의 내면의 소리에 귀 기울이며 한 숨 고르는 시간을 갖는 프로그램입니다.', '1일차;16:00~16:20 사찰 도착, 방사 안내;16:30~17:00 오리엔테이션;17:00~18:30 휴식;18:30~18:50 저녁 예불;18:50~19:50 참선명상 입문 또는 요가 또는 걷기명상(요일별 상이);19:50~20:30 걷기 명상;20:30~21:30 자율 정진;21:30~00:00 취침;2일차;04:30~05:00 새벽 예불, 108배;05:00~06:00 새벽 명상;06:00~07:00 아침 공양;07:00~08:00 붓다숲 산책;08:00~09:00 자율 정진 또는 스님과의 차담(수·일요일);09:00~10:00 참선 명상;10:00~10:20 걷기 명상;10:20~11:20 방사 정리, 소감문 작성;11:20~12:00 점심 공양;12:00 퇴실(집으로). 동절기에는 전 일정 30분씩 앞당겨짐', '세면도구(샴푸, 바디클렌저, 비누, 칫솔·치약, 수건 등), 편안한 여벌옷 및 양말, 긴팔 겉옷, 운동화, 개인 물병(텀블러), 우천시 우산, 동절기 방한용품. 방사 내 전자기기 사용 금지(휴대폰은 종무소에 보관).', 60000, '1박 2일', '2024-01-01', '2026-12-31', 20, FALSE, 0, 0),
