    (85, '행복으로 가는 선명상 템플스테이', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/1/7/20260107023826987_1_S.webp', '지금 여기 지금 이순간, 나는 깨어 있는가? 나는 누구인가? 참선과 명상, 혜국 큰스님 법문(또는 선명상)을 통해 스스로 깨어있음을 자각하는 시간.', '1일차;15:00~15:30 접수 및 방사안내;15:30~17:10 용서자비 사경;사찰안내;선명상 소개;17:20~17:50 저녁공양;포행;18:30~19:20 사물명상;저녁예불;19:20~20:10 법문 및 강의(휴강시 선명상);21:00~03:20 취침;2일차;03:20~03:45 기상;세면;03:50~04:10 새벽예불;04:10~04:20 걷기명상;04:30~05:30 선명상(요가명상);06:00~07:50 아침공양;포행;09:00~10:00 선명상(좌선명상);10:00~10:30 느낌 나누기;소감문 작성;10:30~11:00 숙소정리;퇴실', '편한 복장(여벌옷 필수), 세면도구, 양말, 개인 물병, 모자, 편안한 운동화, 어르신 돋보기 안경(사경시). 하절기 벌레약/모기약, 동절기 방한용품.', 80000, '1박 2일', '2025-07-31', '2026-12-31', 20, FALSE, 0, 0),
    (85, '당일 체험형 프로그램', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/1/7/20260107025408522_1_S.webp', '떠나고 싶을 때, 쉬고 싶을 때 우리가 꿈꾸는 바로 그 여행 떠나고 싶습니다. 쉬고 싶습니다.
