    (86, '달아 달아 밝은 달아 갓바위 부처님과 놀던 달아 ~~~ 추석 템플스테이', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_19184_S.webp', '추석 명절을 팔공산의 정기가 가득한 선본사 갓바위에서 달맞이하는 프로그램. 갓바위 부처님을 친견하며 자유로이 산책, 독서, 기도, 산행하는 템플스테이.', '1일차;15:00~15:40 고불식;15:40~16:20 사찰안내 및 팔상성도 벽화 설명;17:00~17:30 저녁공양;18:00~18:10 사물 관람;18:10~20:00 갓바위 부처님 친견(자율);21:00~04:10 취침;2일차;04:30~04:50 기상;04:50~05:05 새벽예불;05:05~05:55 108배;06:00~06:20 고요함 찾기(선명상);06:20~07:00 차담;07:10~07:40 아침공양;08:00~09:00 3층 석탑 다녀오기;09:00~10:00 방사 정리;10:00~11:00 퇴실', '수건, 칫솔, 텀블러, 속옷, 바람막이, 양말, 여벌옷, 우천시 우비/우산/슬리퍼, 운동화(산행용), 등산용 스틱, 개인상비약 등. 참가복(여름용) 지급.', 60000, '1박 2일', '2026-08-01', '2026-12-31', 20, FALSE, 0, 0),
    (86, '우리의 소원은 (당일형)', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_24880_S.webp', '팔공산 선본사 갓바위에서 당일형 템플스테이를 운영합니다. 아래 프로그램중 사찰안내와 갓바위 부처님 참배와 그 외 1개 프로그램 선택 가능하십니다. 프로그램 :108 소원염주만들기, 명상, 차담, 사찰안내(선택),갓바위 산행(선택) 팔공산의 수려한 자연환경과 선본사템플스테이 당일형 프로그램으로 일상에서 잊고 살았던 소중한 내 꿈을 다시 알아차리고, 꿈을 이루기 위해 열심히 노력할 수 있는 에너지를 충전하는 프로그램입니다. 당일형은 5명 이상 되어야 운영되오니 인원이 모자랄시 취소 될수 있음에 양해 부탁드립니다. *개인차량을 이용하시는 분들은 차량번호 (예시: 00 가 1234 )를 참가자 성함과 참여날짜도 함께 문자 남겨주세요. 만일 차량통제 바가 자동으로 안 올라가면 버튼 누르신 후 연결 되면 템플스테이 참가자 라고 말씀하시면 통과 가능하십니 다. * 소모임 또는 단체 신청 가능하며, 프로그램과 운영시간은 모임 성격에따라 맞춤진행가능합니다. * 010-2631-1868 (오전 09시 ~ 오후 5시)로 문의 전화 주세요.', '1일차;12:40~13:00 도착;13:00~14:30 스님과 차담 또는 108염주꿰기,연꽃등만들기 중 택 1;15:00~16:00 사찰안내;15:00~17:00 갓바위 참배;16:00~18:00 갓바위 부처님 참배 후 집으로 귀가', '* 운동화 또는 등산화, 생수, 등산스틱 ,우천시 우산 또는 우의', 30000, '당일', '2025-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (86, '갓바위 부처님 품에서 잠시 쉬어가기', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_25298_S.webp', '전국 일등 기도도량 팔공산 선본사 (갓바위) 템플스테이 입니다. 바쁘고 지친 일상을 벗어나 갓바위 부처님 품 속에서 잠시 쉬며 마음을 비우는 힐링 프로그램입니다. * 꼭 읽어봐주세요 * 선본사 템플스테이관에서 갓바위 부처님께 가시려면 30-40분 정도 걸으셔야 하오니 다리가 불편하신 분들은 등산용 스틱을 준비해 오시면 도움이 됩니다. * 추가프로그램(108 소원 염주꿰기, 연꽃등 만들기 등)을 운영하오니 예약시 전달 사항에 신청 해주세요. * 예약 후 차량가자고 오시는 분은 010-2631-1868 로 오시는 날짜와 성함, 차량 번호를 문자로 보내주세요. * 예약은 최대 2박 3일이며 기간 연장여부는 전화상담 후 결정됩니다. * 남 녀 방사 구분하며 참가자가 많을시 다른분과 같은방 사용하실 수 있음에 양해 부탁드립니다. * 부득이 하게 가족(개인)방 사용을 원하실 경우 전화상담 후 예약 해주세요. - 주중 가족방(개인방) 참가비는 1인당 8만원 입니다.- 개인방 원하시면 미리 문자 연락 부탁 드립니다. - 가족(개인)방 예약은 2인 이상시 신청 가능하며 큰방과 욕실이 있습니다. * 사찰 사정상 일부 프로그램은 조정될 수 있습니다. * 미성년자 참가시에는 보호자의 동의서가 필요합니다. * 땀이 많이 나는 계절에는 여유분의 옷을 가져오시면 쾌적 합니다. (참가복은 하절기 티 와 바지, 동절기 조끼와 바지 지급 합니다)

- 예약 후 바로 결재부탁드립니다. 미결재시 예약이 취소될 수 있음을 안내드립니다.

- 초등학생포함 학생(미성년자)의 경우 부모님 동반하에 템플스테이체험이 가능합니다.

- 미성년 학생들만 예약할 경우 자동 취소될수 있음을 안내드립니다.

- 템플스테이 중 안전관리와 보험적용을 위하여 모든예약은 실명으로  부탁드리며 타인의 명의를 도용하는 등 허위 정보로 예약된경우, 시설관리권에 의거하여 별도의 통보없이 예약취소 및 현장 퇴방조치를 할 수있음을 안내드립니다', '1일차;14:30~14:50 방사안내 및 수련복 지급;15:00~16:00 고불식 및 사찰안내;16:00~16:30 휴식;16:30~17:10 저녁 공양;17:30~20:00 갓바위 부처님 참배 (자율);20:30~21:00 휴식;21:00~04:00 소등 및 취침;2일차;04:50~05:10 새벽 예불(극락전) 자율 - 하절기;05:10~07:00 108배, 고요함 찾기 (선명상), 스님과 차담 ( 템플스테이관 1층 법당) 자율 - 하절기;05:20~05:35 새벽 예불(극락전) 자율 - 동절기 10/1일부터;05:35~07:00 108배, 고요함 찾기 (선명상), 스님과 차담 ( 템플스테이관 1층 법당) 자율 - 동절기;07:10~07:40 아침 공양;08:00~10:00 3층 석탑 또는 갓바위 다녀오기 (자율);10:30~10:40 화장실, 방사환경을 처음처럼 ~;10:50~11:00 부처님께 인사;11:00~00:00 삶의 터전으로 ~', '* 수건, 칫솔, 텀블러(정수기 사용),속옷, 바람막이, 양말, 여벌옷 우천시 - 1.우비(갓바위 참배시 유용합니다), 우산 - 2.슬리퍼 * 운동화(산행용), 등산용 스틱(무릎이 않좋은신분 중 개인차량으로 오시는분은 챙겨오시면 좋아요^^) 개인상비약 등 * 참가복은 여름 (티, 바지) 지급합니다. * 양말 (사찰 내에서는 맨발로 다니지 않는것이 예의 입니다.) * 외투 (산사는 하루의 일교차가 큰 편이오니 보온에 필요한 겉옷 챙겨 오세요)', 50000, '1박 2일', '2023-04-01', '2026-12-31', 20, FALSE, 0, 0);

