    (87, '마음 돌보는 템플스테이 - (1박 2일 체험형)', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/3/18/20260318115301356_1_S.webp', '호흡명상, 걷기명상, 일상 마음챙김을 통해 지금 이 순간 깨어있음을 알아차리고 마음챙김과 자애의 힘으로 번뇌를 다루며 마음의 평화를 지켜가는 시간을 백양산 선암사에서 갖는다. 최소 3인 이상 신청 시 진행됩니다.', '1일차;14:40 사찰 도착;15:00 OT 및 사찰 예절 안내;16:00 도량 안내;17:20 저녁 먹기 명상;18:15 타종 체험 및 저녁 예불;19:30 연꽃 등 만들기(마음 챙김);20:30 자율 산책 후 취침 명상;2일차;04:00 자율 새벽 예불;05:30 자율 아침 해맞이 명상;06:30 아침 먹기 명상;07:30 자율 갈맷길 또는 솔숲 걷기 명상;09:40 스님과의 차담;10:40 후기 작성 및 방사 정리;11:00 귀가', '개인 세면도구, 수건, 편한 여벌 옷 및 편한 운동화, 양말, 개인 텀블러(차 음용 시 필수). 동절기에는 개인 방한용품 추가', 100000, '1박 2일', '2026-04-01', '2026-12-31', 20, FALSE, 0, 0),
    (87, '마음 쉬어가는 템플스테이 - (1박 2일 자율 휴식 체험형)', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/3/18/20260318114813967_1_S.webp', '호흡명상, 걷기명상, 일상 마음챙김을 통해 지금 이 순간의 깨어있음과 알아차림을 익혀 탐욕과 성냄을 극복하는 마음챙김과 자애명상으로 마음의 평화를 가꾸어 가는 시간을 백양산 선암사에서 갖는다. 최소 3인 이상 신청 시 진행됩니다.', '1일차;14:40 사찰 도착;15:00 OT 및 사찰 예절 안내;16:00 도량 안내;17:20 저녁 먹기 명상;18:15 타종 체험 및 저녁 예불;19:30 108배 체험 + 108염주 만들기(사전 신청);20:30 자율 산책 후 휴식 및 취침 명상;2일차;04:00 자율 새벽 예불;05:30 자율 아침 해맞이 명상;06:30 아침 먹기 명상;07:30 자율 갈맷길 또는 솔숲 걷기 명상;09:30 스님과의 차담;10:40 후기 작성 및 방사 정리;11:00 귀가', '개인 세면도구, 수건, 편한 여벌 옷 및 양말, 편한 운동화, 개인 텀블러(차 음용 시 필수). 동절기에는 개인 방한용품 추가', 100000, '1박 2일', '2026-04-01', '2026-12-31', 20, FALSE, 0, 0),
    (87, '반야심경 사경 - 마음의 평온과 집중의 시간', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/9/18/20260918011359046_1_S.webp', '반야심경 사경(경전을 직접 베껴 쓰는 수행)은 몸과 마음을 청정하게 하고 무량한 복덕과 공덕을 쌓는

불교의 대표적인 수행법입니다.

한 자 한 자 정성껏 글자를 써 내려가는 과정은 복잡한 생각을 비우고 고도의 집중력을 길러주어 마음을

차분하게 가라앉혀 마음의 평온과 집중을 통하여 자신의 잠재의식을 들여다보고, 마음의 중심을 잡는

내면 성찰의 소중한 수행을 체험 할 수 있는 시간입니다.

✅ 유의사항

본 프로그램은 최소 3인 이상 신청 시 진행됩니다.

최소 인원 미달 시 예약이 취소 될 수 있습니다.

예약 후 24시간이내 입금 미 확인 시 예약이 자동 취소됩니다.

환불 시 이체 수수료 차감 된 금액으로 환불됩니다.

프로그램 일정은 내부 사정에 따라 변동될 수 있습니다.

✅방사 안내

남.여 혼숙 불가로

남.여 구분하여 랜덤 배정 진행 됩니다.

어린이 동반 가족은 한방으로 배정해 드립니다.

✅미성년자 참가 안내

미성년자 참가 시, 반드시 보호자의 동의가 필요 합니다.

초등학생 이하 참가 시 반드시 보호자 동반하셔야 되며

미성년자 참가 동의는 안내 문자에 기재된 전화번호로 보호자가 직접 문자를 보내 주셔야 됩니다.

✅예약 및 환불 안내

템플스테이 참가 예약 --> 온라인(예약 사이트) 예약만 가능합니다.

예약 후 24시간이내  결제까지 완료 되셔야  예약 확정입니다.

환불금 진행 --> 모든 환불금 진행 시 이체 수수료 제외 후 환불 진행됩니다.

환불금 요청 -->  예약 홈페이지 로그인 후 취소, 요청 신청 하시면 됩니다.

환불금 계좌를 알려주시면 접수 후 5일내 환불 처리 됩니다

✅상담 안내

매주 월, 화요일은 템플스테이관 휴관일 입니다.

수~일요일 09:00 ~ 17:00 전화상담 051.805.7573

