    (88, '2026년 휴식형 - 에어컨 없습니다.', '휴식형', 'https://ts-cdn.com/ups/templePrg/2025/12/2/20251202105847539_1_S.webp', '인생이란 본디 몸부림치면 칠수록 수렁은 깊어지고 벗어나려 하면 할수록 첩첩산중이니, 그저 머무는 바 없이 머물고 가는 바 없이 가는 것. 예스러움을 간직한 조계산 선암사의 고즈넉한 풍경 속으로 떠나는 자율형 휴식 프로그램. 방에 에어컨이 없다.', '1일차;14:00 방사 안내 및 템플복 지급;17:00 사찰 예절;17:30 저녁 공양;18:30 저녁 예불;21:00 취침;2일차;03:40 새벽 예불;05:50 아침 공양;08:30 스님과의 차담;11:30 점심 공양;12:00 귀가', '세면도구(칫솔, 치약, 수건, 샴푸 등), 양말, 운동화, 얇은 가디건 등', 50000, '1박 2일', '2026-01-01', '2027-01-01', 20, FALSE, 0, 0),
    (89, '[휴식형] [상시] 구름, 바람 그리고 休', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/6/26/20260626023434968_1_S.webp', '언제든 선운사에 오셔서 편히 쉬는 프로그램입니다.

몸과 마음을 쉬며 숲길을 걷노라면,

