토요일 신안사에서 점심 식사 후 약 4시간 진행됩니다. 기왓장 그림 그리기를 통해 전통 기와 위에 나만의 색을 입혀 보세요. 완성된 작품은 신안사의 기운을 담아 댁으로 가져 가실 수 있습니다.

