    (105, '나를 듣는 시간 - 소리와 몸으로 만나는 내 마음 & 사찰 음식 체험', '당일형', 'https://ts-cdn.com/ups/templePrg/2025/3/3/20250303124906157_1_S.webp', '&diams; 일상에서 잠시 벗어나 있는 그대로의 나를 만나고 싶은 분, 도심 속 힐링 전통사찰 심택사로 오세요!

    몸과 마음의 휴식이 필요하신 분은 도심 속 힐링 전통사찰 심택사로 오세요!

&diams; 소리명상, 몸의 움직임, 색, 이미지 등 다양한 예술적 표현을 통해 나의 감각을 직접 경험하는 예술 명상 프로그램으로 진행합니다.

&diams; 매회 하나의 주제를 중심으로 진행되며, 당일 참여자의 연령, 인원, 구성 및 특성을 고려하여 명상활동의 내용과 진행 방식이 달라질 수 있습니다.

&diams; 판단과 생각을 잠시 내려놓고, 일상 속에서 놓치고 있던 몸의 감각과 진실된 속마음의 움직임을 바라보며 나에게 돌아오는 시간을 가져 보세요.

► 단체 예약은 ** 010-7471-4509**로 문의하시면 친절히 상담해 드립니다.

► 주말 단체 예약은 사전 협의하여 운영 가능합니다.

► 사찰 사정에 따라, 3인 미만인 경우 취소될 가능성이 있습니다. 그럴 경우 3일 전 연락드리겠습니다.

► 당일 참가 인원 및 참여자의 특성에 따라 명상 및 예술활동의 세부 내용은 변경될 수 있습니다.', '1일차;11:00~11:30 첫인사 및 도량안내;11:30~12:30 간단한 불교문화 체험;12:30~13:00 사찰 음식 체험 및 공양하기;13:00~15:00 감각으로 만나는 나 - 예술명상;15:00~15:30 마음 나누기 및 회향', '&diams; 활동하기 편한 복장으로 오시기 바랍니다.

&diams; 개인물병 있으면 좋습니다.(개인 선택사항)

