    (111, '주지스님과함께 법화경 철야독송', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/4/4/20260404052238932_1_S.webp', '지리산 피아골 천년고찰 청정기도 도량 연곡사에서 주지스님이 집전하시는 철야기도를 체험해보고 부처님의 가피를 받아보는 프로그램. 밤 9시부터 새벽 3시40분까지 대적광전에서 법화경 철야독송을 진행한다.', '1일차;15:00~16:00 방사안내;복장지급;도량안내; 17:00~17:30 저녁공양; 18:00~19:00 저녁예불; 21:00 법화경 독송 시작(다음날 4시까지 이어짐);2일차;03:00~03:40 법화경독송 마무리; 05:00~06:00 새벽예불; 07:00 아침공양; 08:00~09:00 주지스님과 차담(자율); 11:00 퇴실', '개인 세면도구, 수건, 칫솔, 개인물병 (각 방사마다 샤워시설·에어컨·전기포트·드라이기 완비)', 100000, '1박 2일', '2026-04-04', '2027-04-24', 20, FALSE, 0, 0),
    (111, '마음쉬는 피아골', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/1/30/20260130023624798_1_S.webp', '** 2인 이상 신청** 고요히 자신을 돌아보며 스트레스와 부담감을 덜어내고 자신에게 주는 휴식과 안정의 시간으로 평안한 마음을 회복할 수 있는 기회입니다. 사찰의 기본 규칙을 지켜주시며 자유롭고 편안하게 머무시면 됩니다. 지리산 피아골의 절경과 고즈넉하고 아늑한 연곡사에서...(각 방마다 개별 화장실, 에어컨이 있습니다.) ☎ 문의전화 템플스테이 : 010-5227-1080 , 종무실 : 010-5131-7412, 061) 782-7412', '1일차;14:00~15:30 방사배정, 복장지급, 도량안내;16:00~17:00 동승탑 북승탑걷기(자율);17:00~17:30 저녁공양;18:00~18:40 저녁예불(자율);21:00~00:00 취침;2일차;05:00~06:00 새벽예불(자율);07:00~07:30 아침공양;08:00~09:00 스님과의 차담(자율);10:00~11:00 사시불공(자율);11:00~11:00 방사 뒷정리,퇴실', '개인 세면도구, 수건, 칫솔,개인물병 준비해오시면됩니다. * 각 방사마다 샤워시설 에어컨이 완비되어 있습니다. * 방사 내 전기포트 드라이기 준비 되어 있습니다.', 60000, '1박 2일', '2025-01-01', '2027-12-31', 20, FALSE, 0, 0),
