    (113, '(1박2일) 마음이 머무는 하루, 연운사 카라반 템플스테이', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/8/10/20260810084945811_1_S.webp', '절에서 잠들고 카라반에서 깨어나는 특별한 산사 체험. 예불·차담·사찰 풍경을 천천히 마주하며 쉬는 1박2일 프로그램으로, 도심 가까운 김포 연운사에서 진행된다. 독립형 카라반 1대 기준 일행 최대 4명까지 예약 가능.', '1일차;10:00~10:30 접수;방사안내;수련복 착용; 10:30~11:30 사시예불 및 스님법문; 11:30~12:30 점심공양; 14:00~14:30 나만의 단주 만들기; 14:30~15:10 선명상; 15:10~16:00 스님과 차담; 16:00~17:00 비움과 쉼의 시간; 17:00~17:40 저녁공양; 17:40~20:00 자유참배·발원지 쓰기; 20:00 휴식·취침;2일차;04:50 새벽 범종 타종(자율); 05:00~05:40 새벽예불(자율); 07:30~08:00 아침공양; 08:00~08:30 마음걷기(자율포행); 08:30~09:00 소감나누기;설문작성;퇴실', '개인 세면도구(칫솔·치약·샴푸·바디워시 등), 단정한 편안한 옷, 개인 물병 또는 텀블러, 개인 복용약, 휴대전화 및 충전기, 계절별 방한용품', 70000, '1박 2일', '2026-08-01', '2026-10-31', 20, FALSE, 0, 0),
    (113, '(당일형)반려견과 함께하는<멍플스테이>', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/3/4/20260304113955789_1_S.webp', '김포 연운사 멍플스테이 프로그램은 반려견과 함께하는 당일형 템플스테이 프로그램입니다.
도심 속 사찰 김포 연운사에서 사랑하는 반려견과 함께 마음을 쉬어가는 특별한 시간을 마련했습니다.
김포 연운사 멍플스테이는 사람과 반려견이 함께 머물며 평온함과 따뜻한 쉼을 느낄 수 있는 시간입니다.
애견행동전문가의 상담, 마사지, 행동교정수업, 산책 등 반려견의 마음과 행동을 이해하고 사람과 반려견이 더 깊이 교감할 수 있도록 돕는 프로그램입니다.
사랑하는 반려견과 함께하는 하루가 마음에 오래 남는 작은 쉼표가 되길 바랍니다.
