바쁜 일상에서 잠시 벗어나

고요한 사찰에 머물며 나의 마음을 돌아보는 시간입니다.

선명상으로 마음을 가라앉히고,

천천히 걸으며 주변의 소리에 귀 기울여 봅니다.

특히 불자 참가자들을 위해 별도의 프로그램으로 정해진 기도시간 외에도,

각자의 인연과 발원에 따라 자유롭게 기도하고 포행할 수 있는 시간을 마련합니다.

누군가는 법당에서 조용히 기도하고,

누군가는 경내를 천천히 걸으며 자신의 마음을 바라보고,

또 누군가는 아무것도 하지 않고 고요히 머물러도 좋습니다.

저녁에는 스님과 차 한 잔을 나누며 이야기를 듣고,

이른 새벽에는 함께 예불을 올리며 하루를 시작합니다.

무언가를 많이 하기보다,

잠시 멈추어 나 자신을 바라보는 시간.

연운사에서 조용히 쉬어가세요.

