    (115, '은행나무처럼...', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_124_S.webp', '충북의 설악, 천태산에 자리잡은 천년고찰 영국사에서 진행하는 체험형 프로그램. 사찰 소개, 문화재 탐방, 108배, 주지스님과의 차담, 망탑봉 트래킹을 포함한다.', '1일차;15:00~15:30 도착 및 방사배정; 15:30~16:30 사찰소개 및 예절습의; 영국사 문화재 탐방; 17:00 저녁공양; 18:00~18:30 저녁예불 및 108배; 21:00~21:30 취침준비 및 취침;2일차;05:00~06:00 새벽예불; 07:00~07:20 아침공양; 07:30~08:30 주지스님과의 차담; 09:00 망탑봉 산책; 11:00~11:30 방정리 및 소감문 작성; 11:30~12:00 점심공양 후 회향', '개인 세면도구, 수건, 칫솔, 여벌옷(외투), 운동화, 양말, 개인 물병, 겨울철 방한용품 및 아이젠', 70000, '1박 2일', '2026-03-01', '2026-12-31', 20, FALSE, 0, 0),
    (115, '은행나무에서', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_19921_S.webp', '천년고찰 영국사는 충청북도에서 문화재와 보물이 두번째로 많은 사찰입니다.
문화재와 보물이 잘 보존된 영국사에서 당일 체험으로 문화재와 보물을 돌아보며 천년의 숨결을 느껴보세요.', '1일차;11:30~12:00 도착 및 신청서 작성;12:00~13:00 점심공양;13:00~14:00 문화재탐방;14:00~15:00 스님과의 차담;15:00~15:30 회향', '텀블러, 운동화 (편한신발), 모자, 필기도구, 여벌옷(겉옷)', 30000, '당일', '2026-08-01', '2026-12-31', 20, FALSE, 0, 0),
    (116, '스님과의 참선', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/8/20/20260820104406539_2_S.webp', '산사에서의 기도와 참선을 통하여 어지러운 마음을 내려놓으며 자신을 돌아보는 시간을 갖는 체험형 프로그램. 10명 이상 단체가 사전 상담 후 신청 가능하다.', '1일차;15:00~16:00 입소;안내;방배정; 16:00~17:00 사찰 둘러보기 및 휴식; 17:00~17:30 저녁공양; 18:00~18:30 저녁예불;2일차;06:00~07:00 새벽예불; 07:00~07:30 아침공양; 07:30~10:00 개인별 산책 및 휴식; 10:00~11:00 사시예불; 11:00~11:30 방사정리·소감문·설문조사; 11:30~12:00 점심공양 후 퇴소', '손수건, 칫솔, 치약, 물병 등 개인물품', 70000, '1박 2일', '2024-07-01', '2026-11-30', 20, FALSE, 0, 0),
    (116, '고요한 산사에서의 휴식', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/9/8/20260908042935139_1_S.webp', '천천히 걷고, 천천히 말하고, 천천히 생각하는 휴식형 템플스테이. 수목원 산책이나 마을길 산책 등 자유로운 휴식 시간을 중심으로 구성된다.', '1일차;14:30~15:30 접수 및 방사안내;수련복 지급;사찰안내; 15:30~17:00 휴식(수목원 또는 마을길 산책); 17:00~17:30 저녁공양; 18:00~18:30 저녁예불;2일차;06:00~07:00 새벽예불; 07:00~07:30 아침공양; 07:30~10:00 휴식(수목원 또는 마을길 산책); 10:00~11:30 사시예불(자율); 11:30~12:00 점심공양; 12:00 설문조사·참가후기 작성 및 방사정리 후 퇴실', '개인 세면도구, 수건, 칫솔, 여벌옷(면티·가벼운 바지), 운동화, 양말, 개인 물통, 동절기 방한용품', 70000, '1박 2일', '2023-01-01', '2026-11-30', 20, FALSE, 0, 0),
    (116, '당일형 - 예불참여및 사찰 알아가기', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/3/31/20260331020954039_2_S.webp', '진흙속에서도 아름답게 피어나는 연꽃처럼, 연꽃잎 양초에 자기의 소원을 밝히고,  부처님의 가르침을 알아가는 당일체험입니다.', '1일차;08:30~09:00 입소 및 사찰 안내;09:00~10:00 사찰예절 알아가기;10:00~11:30 사시예불;11:30~12:00 점심공양;12:00~13:00 휴식 또는 수목원 산책;13:00~15:00 참가 소감문 작성후 퇴소', '개인 세면도구, 수건, 칫솔, 여벌옷(면티,가벼운바지), 운동화(편한 신발), 양말, 개인 물통 *동절기에는 개인방한용품 준비하세요.', 30000, '당일', '2025-09-01', '2026-10-31', 20, FALSE, 0, 0),
    (117, '싱잉볼 선명상 템플스테이(고요가 울리는 순간, 마음이 맑아집니다.)', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/9/16/20260916065529536_1_S.webp', '저녁 햇살이 산허리를 스치는 시간, 싱잉볼의 울림과 호흡을 하나로 맞추며 마음을 비워내는 선(禪) 체험 프로그램. 스님의 안내로 싱잉볼 소리에 집중해 긴장과 피로를 풀어내는 명상 시간을 갖는다.', '1일차;15:30~15:50 도착;방사배정 및 수련복 환복;16:00~17:00 명상 안내(오리엔테이션);17:30~18:30 저녁공양 및 휴식;18:30~21:00 싱잉볼 선(禪) 명상;21:30~00:00 고요한 꿈 명상;2일차;04:00~05:30 새벽예불 및 호흡명상;06:00~06:30 아침공양;07:30~08:30 마음챙김명상;08:30~09:30 스님과의 차담 힐링 토크;10:00~11:00 홀로 숲길 걷기 명상;11:00~11:50 소감문 작성 및 방사 청소 후 회향;11:50~12:30 점심공양', '개인 세면도구(비누·치약 제공), 수건, 여벌 옷(외투, 점퍼), 운동화 또는 경등산화, 개인 물병(텀블러), 손전등. 사찰 수련복(상하의)·비누·치약·헤어드라이어 기본 제공. 슬리퍼 불가, 양말 필수.', 100000, '1박 2일', '2025-01-11', '2026-12-26', 20, FALSE, 0, 0),
    (117, '"산사의 체험" 템플스테이', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_16005_S.webp', '일상의 스트레스와 심신의 피로를 돌아보고 수행자의 자세로 내면을 살펴보는 체험형 템플스테이. 스님과의 차담, 명상 수행을 통해 마음을 내려놓고 삶을 성찰하는 시간을 갖는다.', '1일차;15:30~15:40 도착 및 방사 배정;15:40~15:50 수련복 환복;16:00~17:00 사찰예절 및 도량 안내;17:30~18:00 저녁공양;18:00~18:55 휴식;19:00~21:00 스님과의 백련꽃 차담;21:00~21:30 세면 및 취침;2일차;04:00~05:30 새벽예불 및 호흡명상(자율);05:30~06:00 휴식;06:00~06:30 아침공양;06:30~08:50 포행(산책) 및 휴식;09:00~10:20 108배 염주만들기 체험;10:30~11:50 환복 및 방사정리;12:00~12:30 점심공양 후 회향(퇴실)', '개인 세면도구(비누·치약 제공), 수건, 여벌 옷(외투, 점퍼), 운동화 또는 경등산화, 개인 물병(텀블러), 손전등. 사찰 수련복(상하의)·비누·치약·헤어드라이어 기본 제공. 슬리퍼 불가, 양말 필수.', 80000, '1박 2일', '2025-09-05', '2026-11-28', 20, FALSE, 0, 0),
    (117, '"산사의 휴식" 템플스테이', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_17769_S.webp', '사찰 예절을 배우고 명상과 사색을 하며 산사에서 시간을 보내는 휴식형 프로그램. 독서, 포행(산책), 마음 성찰 등을 통해 여유로운 시간을 갖고 스님과의 차담과 예불로 마음을 내려놓는다.', '1일차;15:30~15:40 도착 및 방사 배정;15:40~15:50 수련복 환복;16:00~17:00 사찰예절 및 도량 안내;17:30~18:00 저녁공양;18:00~18:55 휴식;19:00~21:00 스님과의 차담;21:00~21:30 세면 및 취침;2일차;04:00~05:30 새벽예불 및 호흡명상(자율);05:30~06:00 휴식;06:00~06:30 아침공양;06:40~11:00 포행(산책), 명상, 휴식;11:00~12:00 방사 정리 및 환복;12:00~12:30 점심공양 후 회향(퇴실)', '개인 세면도구(비누·치약 제공), 수건, 여벌 옷(외투, 점퍼), 운동화 또는 경등산화, 개인 물병(텀블러), 손전등. 사찰 수련복(상하의)·비누·치약·헤어드라이어 기본 제공. 슬리퍼 불가, 양말 필수.', 60000, '1박 2일', '2025-10-30', '2026-11-30', 20, FALSE, 0, 0),
    (117, '지친 마음을 비우는 단 하나의 소리,  싱잉볼 선(禪)명상', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/9/16/20260916065613885_2_S.webp', '바쁜 삶 속에서 몸은 잠들어도 마음은 쉬지 못할 때가 있습니다.
싱잉볼 선명상은 그 지친 마음을 위한 고요한 치유의 시간입니다.
티베트에서 전해 내려온 싱잉볼의 공명과 울림은 신체와 뇌파의 진동 주파수와 맞닿아
긴장 · 피로 · 불안 · 스트레스를 자연스럽게 풀어냅니다.
울림을 듣는 것만으로도 얕은 호흡이 깊어지고, 흩어진 마음이 중심을 찾게 됩니다.
어떤 수행이나 의지가 필요하지 않습니다.
그저 소리가 머무르고 사라지는 과정을 함께 바라보는 것, 그것이 이 명상의 핵심입니다.
지친 감각을 깨우고, 닫힌 마음을 열며, 삶의 속도를 조절하는 시간!
싱잉볼 선명상으로 내면의 평온을 다시 설계해보십시오.

지친 마음을 비우는 단 하나의 소리,  싱잉볼 선(禪)명상은
매월 첫째 주에 시작해 총 4번 진행합니다.
금요일반, 토요일반, 일요일반으로 구성되며 참가비는 1십만원입니다.
* 첫째 주에 참여하지 못하시는 경우 1회, 2회 참가를 해도 강습비는 1십만원입니다.
매월 첫째 주에 참여해주시길 부탁드립니다.
* 원활한 안전 관리와 보험 적용을 위해 모든 예약은 실명으로 이루어져야 합니다.
