탐욕과 갈등으로 넘실대는 현대사회로부터 동떨어진 채 아름다운 선지식의 향기와 전통 불교문화의 원형을 잘 보존해온 산사에서 완전하고도 평화로운 자유와 안락한 휴식을 보장받도록 설계된 템플스테이 프로그램입니다.

사찰의 절제된 일상으로 자발적으로 참여함으로써 맑고 깨끗한 수행자의 삶을 귀감으로 삼으셔도 좋고, 공양 시간만 준수하고 다른 일정은 거부한 채로 완전한 자유시간을 누리셔도 좋습니다.

사무국과 조율하셔서 자유로이 명상하시거나 산책을 하시거나 독서를 하시는 데 도움되는 지원을 받으세요(도서 대출, 문화재 관람, 염주 꿰기 등).

아름다운 산사에서 아름답게 휴식하고 싶으신 분들은 연중 열려있는 예천 용문사의 산문을 찾아오세요. 두 팔 벌려 환영합니다.

◎ 문화재 관람

    - 예천 용문사는 성보박물관을 운영할 정도로 보물급 문화재를 원형 그대로 잘 보존해 오고 있는 방문가치가 높은 사찰입니다.

    - 전국 유일의 윤장대 원형보존 사찰입니다.

◎ 조석예불은 강권하지 않습니다. 자율적으로 참가여부를 선택하실 수 있습니다.

◎ 자율명상 시간은 개인적인 휴식시간을 보내시는 시간입니다. 사무국과의 조율을 통해 원하시는 명상의 물품지원을 받으실 수 있습니다.

    1. 108배(108염주 만들기 키트 제공)

