이번 프로그램에서는 자극적인 일상의 식탁에서 벗어나, 자연이 준 선물 본연의 향과 맛에 집중해 봅니다. 조리 과정에서 생겨나는 모든 것에 감사하며, 이웃과 자연을 해치지 않고 상생하는 법을 배웁니다.

