    (128, '천불천탑, 미완의 꿈(휴식형)', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_28653_S.webp', '-. 휴식형 템플스테이는 운주사에서 자율적으로 몸과 마음의 휴식을 취하고 편안하게 자기 자신만의 시간을 갖는 프로그램입니다. -. 사찰에서의 기본예절은 지켜주셔야 하며, 예불, 공양, 스님과의 차담, 천불천탑길 해설산책 등의 프로그램이 가능하며, 그외는 자유롭게 머무시면 됩니다. -. 1년 365일 언제나 가능하며, 최대 기간은 3박 4일입니다.', '1일차;14:00~14:30 방사 배정 후 자율 산책;17:00~17:30 저녁공양;18:00~19:00 스님과의 차담(자율);19:00~20:00 천불천탑길 포행 (자율);21:00~21:30 취침준비 및 취침;2일차;04:50~05:30 새벽예불 (자율);07:00~07:30 아침공양;08:00~09:30 천불천탑길 해설산책(자율);10:00~11:00 휴식, 정리 정돈 퇴실', '세면도구(수건, 샴푸, 칫솔 포함) 및 편안한 여벌 옷, 우산, 모자, 개인 물병, 운동화(편안한 신발) 등 * 동절기에는 장갑 모자 등 개인 방한용품 준비하세요.', 60000, '1박 2일', '2026-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (129, '인생 No답 템플스테이(체험형) - "인생을 살아가는데 답이 있을 까?"', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_29792_S.webp', '인생을 살다보면 내가 잘 살고 있는 건지, 남들보다 뒤처진 삶을 사는 것은 아닌지 의심이 생기고 조급해질 때가 많다. 템플스테이를 통해 세상을 바라보는 새로운 관점을 배우고 생각의 프레임을 부수며 삶을 새롭게 refresh하는 시간.', '1일차;15:00 도착·유의사항·물품지급 및 숙소배정;15:30~16:00 템플 환복 후 개인정비;16:00~17:00 사찰 안내;17:00 저녁 공양;18:00 타종 체험;18:00~18:30 저녁 예불(대웅전);18:30~19:30 스님과 차담;21:00 취침 및 소등;2일차;05:20 새벽 예불(대웅전);06:30 아침 공양;07:30~08:00 숲터널 걷기 명상(자율);08:00~09:30 자율 시간;09:30~10:30 108염주 꿰기 or 마음꽃 부채 만들기;10:30~11:20 숙소정리·환복 후 종무실로 이동;11:20~11:30 종무실 도착(체험후기 및 QR코드 작성);11:30~12:00 점심 공양(주중 11:30, 주말·행사일 12:00)', '수건·칫솔·치약 포함 세면도구 일체, 여벌 옷, 슬리퍼, 운동화 또는 등산화(필수), 양말(법당 출입시 필수), 개인물병, 우산, 개인상비약 (드라이기는 숙소 비치)', 60000, '1박 2일', '2025-12-28', '2026-12-31', 20, FALSE, 0, 0),
    (129, '無智性(무지성) 템플스테이(휴식형) - "지금 생각하는 것도 멈춰!"', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_29800_S.webp', '집에 있어도 집에 가고픈, 생각하는 것도 포기하고 싶은 현대인을 위한 휴식형 템플스테이. 무등산을 품은 천년고찰 원효사에서 머무르며 자신을 돌아보고 오직 나만을 위해 투자하는 시간.', '1일차;15:00 도착·유의사항·물품지급 및 숙소배정;15:30~16:00 템플 환복 후 개인정비;16:00~17:00 사찰 안내;17:00 저녁 공양;18:00 타종 체험(자율);18:00~18:30 저녁 예불(자율);18:30~19:30 스님과 차담;21:00 취침 및 소등;2일차;05:20 새벽 예불(대웅전, 자율);06:30 아침 공양;07:30~08:00 숲터널 걷기 명상(자율);08:00~10:30 자율 시간;10:30~11:20 숙소정리·환복 후 종무실로 이동;11:20~11:30 종무실 도착(체험후기 및 QR코드 작성);11:30~12:00 점심 공양(주중 11:30, 주말·행사일 12:00)', '수건·칫솔·치약 포함 세면도구 일체, 여벌 옷, 슬리퍼, 운동화 또는 등산화(필수), 양말(법당 출입시 필수), 개인물병, 우산, 개인상비약 (드라이기는 숙소 비치)', 50000, '1박 2일', '2026-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (131, '我 아-차 선명상 템플스테이', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_457_S.webp', '선명상의 궁극적인 이유는 나의 고통은 물론 타인의 고통을 없애주기 위함이며 차별하고 분별하는 마음에서 벗어나 본래 마음으로 돌아가는 과정. 본래 나의 마음을 찾아가고 알아차리는 지혜를 찾아가는 시간.', '1일차;14:00~15:00 사찰도착 및 방사 배정;15:00~15:30 입재식;15:40~16:50 호흡의 알아차림과 온구체험;17:00~18:00 저녁공양;18:00~18:15 소원을 담은 단주 만들기;18:30~19:30 저녁예불, 나를 알아차리는 108배 절명상;20:00~22:00 자유수행 및 취침;2일차;05:00~06:00 기상 및 새벽예불과 함께하는 호흡명상;06:30~07:30 아침공양;07:30~09:30 숲속 보행 명상;09:30~10:00 선다일미 차명상 후 소감문쓰기;10:00~10:30 방사정리 후 귀가', '개인 세면도구(칫솔, 치약, 수건 기타), 여벌옷(속옷, 바람막이, 외투), 운동화(편한 신발), 개인물병, 스마트폰용 충전기, 개인 상비약 등', 90000, '1박 2일', '2024-08-09', '2026-12-31', 20, FALSE, 0, 0),
    (131, '지장해방소 -지장보살님과 떠나는 스트레스파괴시간', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/8/5/20250805053742205_2_S.webp', '''해방소''는 스트레스로부터의 탈출을 의미하며, 육지장보살님의 가피를 통해 마음 속 억압에서 벗어나 ''진짜 나''를 찾는 여정. 인간계와 내면의 지옥계·아귀계·아수라계·축생계의 고통에서 벗어나 천상계에 도달하는 의미있는 시간.', '1일차;14:30~15:00 도착, 방사배정;15:00~15:30 입재식, 사찰예절;15:30~16:30 온구체험을 통한 마음 깨우기;17:00~18:00 아귀계를 벗어난 저녁공양;18:30~19:30 인간계의 나를 마주하는 비우고 채우는 108배 명상;19:30~22:00 자유수행 및 취침;2일차;04:30~05:00 기상;05:00~06:00 새벽예불, 호흡명상;06:30~07:30 아침공양;07:30~09:00 천상계로의 보행명상;09:00~10:00 소감 발표, 지장해방소 졸업;10:00~10:30 방사정리, 귀가', '개인세면도구(수건포함), 개인물통, 충전기, 드라이기, 양말, 운동화, 여벌의 옷, 겉옷 등 개인용품', 80000, '1박 2일', '2025-09-01', '2026-12-31', 20, FALSE, 0, 0),
    (131, '천상계 템플스테이', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/8/3/20250803112648845_1_S.webp', '편안한 휴식 속에서 답을 찾는 시간. 불교에서 선한 업을 쌓은 이들이 사는 세계를 천상계라 하며, 고통이 적고 즐거움이 많은 복락의 세계로 묘사됨. 선한 삶을 통한 행복을 찾는 휴식 속에서 나를 찾는 시간.', '1일차;14:30~15:00 사찰도착, 방배정;15:00~15:30 입재식과 사찰예절알기;15:40~17:00 쉼;17:00~18:00 저녁공양;18:00~22:00 힐링, 수면;2일차;05:00~06:00 하루 맞이;06:30~07:30 아침공양;07:30~10:00 나를 찾는 시간;10:00~10:30 소감문 쓰기, 방사정리 후 귀가', '세면도구(수건포함), 충전기, 드라이기, 양말, 개인물통, 여벌의 옷, 겉옷, 운동화 등 개인용품', 70000, '1박 2일', '2025-09-01', '2026-12-31', 20, FALSE, 0, 0),
    (132, '눈부신 오늘 (1박2일)', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/1/18/20260118023606413_1_S.webp', '지나친 분별과 생각을 내려놓고 다만 고요히 존재하는 시간. 참된 명상과 크리스탈싱잉볼 치유명상을 경험해볼 수 있는 은해사 체험형 템플스테이.', '1일차;15:00~16:00 도착 및 방사배정;16:20~17:00 오리엔테이션 및 사찰예절 안내;17:00~18:00 저녁공양;18:00~18:30 저녁예불(자율);19:00~20:20 선(禪)명상 & 크리스탈싱잉볼 치유명상;20:50~21:00 세면 및 취침;2일차;05:00~05:10 기상 및 세면;05:25~05:55 새벽예불(자율);06:00~06:40 아침공양;07:00~09:00 자유 시간;쉼의 시간;09:30~10:50 스님과 차담;10:50~11:00 소감문 작성;11:00~11:20 방사정리 후 퇴실', '개인 세면도구, 칫솔, 수건, 여벌 옷(면티셔츠), 외투, 모자, 운동화(편한 신발), 양말, 개인(보온) 물통 (겨울철: 목도리, 모자, 장갑, 점퍼, 마스크, 등산화 등 추가)', 80000, '1박 2일', '2026-01-01', '2026-10-31', 20, FALSE, 0, 0),
    (132, '그냥 이대로(1박2일)', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/1/18/20260118032647360_1_S.webp', '#은해사  #쉼  #그냥이대로  #고요  #자연  #휴식형템플스테이  #치유  #감사

''그냥 이대로'' 정말 괜찮아요.

은해사 휴식형 템플스테이는

일상에서 지친 몸과 마음을 사찰 속 맑은 에너지와 자연환경을 통해 위로 받을 수 있는 프로그램입니다.

은해사 송천길 산책로와 산내암자인 백흥암, 운부암, 기기암, 중암암으로 가는 길은 자연스럽게 우리를 명상으로 이끌어 줍니다.

건강한 사찰음식이 있는 고요한 절집으로

소중한 당신을 초대합니다.

(운영방침)

► 예약 후 입금이 되어야 "예약완료(최종확정)"가 됩니다. 예약 후 3일 이내에 입금이 이루어지지 않을시 자동 취소되며, 다음 참가자에게 넘어 감을 양지 해 주시기 바랍니다.

► 예약 완료후 날짜 변경은 1회 가능하며, 날짜 변경후 취소시 환불 불가합니다.

► 남,녀 방사구분하며 방사크기는 4인실임, 1인 예약시 다른분들과 같이 사용하실 수도 있습니다. 단 참가자가 많지 않은 경우 개별 방사가 제공됩니다.

► 본 프로그램은 최대 2박 3일까지 예약이 가능합니다.

► 1박2일 이상 예약을 원하시는 경우 (1일씩 예약 하시면 됩니다.)

► 임산부는 참여를 금합니다.

► 반려 동물과 동반 참가는 불가 합니다.

► 컵라면 또는 간식은 절대 지참하시면 안됩니다.

► 프로그램 일정은 사찰의 사정에 따라 변경 될수 있습니다.', '1일차;15:00~16:00 도착 및 방사배정;16:20~17:00 오리엔테이션 및 사찰예절 안내;17:00~18:00 저녁공양;18:00~19:00 저녁예불 / 자율참여 (self);19:00~20:50 쉼의 시간;20:50~21:00 세면 및 취침;2일차;05:00~05:10 기상 및 세면;05:25~06:00 새벽예불(자율참여);06:00~06:40 아침공양(06시05분까지 도착);07:00~09:00 각자 자유롭게 산책 / 암자 가기;09:30~10:00 합장주만들기(자율참여);10:00~10:20 소감문 작성;10:20~11:00 방사정리 후 퇴실', '►봄, 여름, 가을참가시 : 개인 세면도구, 치솔, 수건, 여벌 옷(면티셔츠), 외투, 모자, 운동화(편한 신발), 양말, 개인(보온) 물통

►겨울 참가시 : 위와 동일 추가( 방한용품: 목도리, 모자, 장갑, 점퍼, 마스크 등) 등산화 (혹은 미끄러지지 않는 운동화)', 70000, '1박 2일', '2026-01-01', '2026-10-31', 20, FALSE, 0, 0),
    (133, '따뜻한 산사의 품으로 당신을 초대합니다.', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/4/17/20260417041446918_1_S.webp', '나를 위한 정성스러운 하룻밤. 충남 공주의 고요한 산사, 이제사 템플스테이에서 오직 ''나''에게만 집중하는 정성스러운 하룻밤을 제안. 지도법사 스님이 직접 모든 프로그램을 진행.', '1일차;14:00~14:10 행복한 걸음으로..;14:10~14:30 방사 및 도량안내;14:30~15:30 프로그램1;15:30~16:00 프로그램2;17:30~18:30 저녁공양;18:30~19:00 저녁예불(자율);21:00~05:00 취침;2일차;05:00~06:00 새벽예불(자율);07:30~08:30 아침공양 및 방사정리;09:00~10:00 차 한잔의 여유;10:00~11:00 행복한 발걸음으로... (퇴실)', '세면도구(칫솔, 치약, 샴푸, 속옷, 개인수건), 개인 컵(텀블러), 경량 패딩/목도리, 개인 상비약, 운동화', 100000, '1박 2일', '2026-01-20', '2026-12-31', 20, FALSE, 0, 0),
    (133, '일상에 작은 쉼표를 찍다 : 1박2일 휴식형 템플스테이', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/4/17/20260417041321736_1_S.webp', '마침표가 아닌 쉼표가 필요한 당신에게. 끊임없이 이어지는 일상의 문장 속에서 잠시 마침표를 찍기 전, 이제사에서 따뜻한 쉼표 하나를 더하는 시간. 정해진 틀 없이 산사의 흐름에 몸을 맡기는 휴식형 프로그램.', '1일차;14:00~14:10 행복한 걸음으로..;14:10~14:30 방사 및 도량안내;17:30~18:30 저녁공양;18:30~19:00 저녁예불(자율);21:00~05:00 취침;2일차;05:00~06:00 새벽예불(자율);07:30~08:30 아침공양 및 방사정리;09:00~10:00 차 한잔의 여유;10:00~11:00 행복한 발걸음으로... (퇴실)', '세면도구(칫솔, 치약, 샴푸, 속옷, 개인수건), 개인 컵(텀블러), 경량 패딩/목도리, 개인 상비약, 운동화', 80000, '1박 2일', '2026-01-25', '2026-12-31', 20, FALSE, 0, 0),
    (133, '지친 나를 위한 처방전, 외갓집 감성 당일형 템플스테이', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/1/20/20260120052423791_1_S.webp', '도시 소음은 잠시 로그아웃!

시간은 없지만 힐링은 간절한 당신을 위해 이제사가 문을 활짝 열었습니다.
대단하고 거창한 다짐 없어도 괜찮아요.
그저 시골 외갓집에 놀러 온 것처럼 편하게 쉬다 가는 곳,
바쁜 일정 사이, 잠시 이제사 마당에 머물다 가세요.

참가비 : 기본 1인 30,000원


입소시간 : 오전입소 : 오전9시 ~ 오후12시
                  오후입소 : 오후2시 ~ 오후5시
                     * 원하시는 시간대에 편히 머물다 가실 수 있도록, 예약 시 ''이제사 템플 스테이 연수원''에 먼저 확인 부탁드려요.


이제사 템플 스테이 연수원 문의 : 010 2498 5038
