*개인상담은 프로그램 종료 후 가능합니다. (상담 비용 : 1인 시간당 20,000원)


주소 : 충남 공주시 사곡면 다복골길73-6  대한불교조계종 팔봉산이제사


오시는길', '1일차;00:00~00:00 도량안내 / 사물체험 / 스님과 차담 ( 시간 문의 주세요.)', '당일형 프로그램의 경우 준비물이 필요하지 않습니다.', 30000, '당일', '2026-01-20', '2026-12-31', 20, FALSE, 0, 0),
    (134, '마음휴식, 쉼명상', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_1605_S.webp', '고요한 명상센터에서 명상으로 마음을 쉬는 시간. 자비선사는 명상전문사찰로, 수행 중 소화 부담을 줄이고 마음의 안정과 집중을 돕기 위해 저녁은 떡, 감자, 두유 등 가벼운 음식으로 제공.', '1일차;15:00~16:00 방사배정 및 사찰안내;16:00~17:30 자비선명상;18:00~00:00 저녁공양 및 휴식;2일차;07:00~09:00 아침공양 및 휴식;09:00~11:00 자유시간(산책 등);11:00~12:00 방사정리 및 퇴실준비', '세면도구, 수건, 모자, 개인물병', 60000, '1박 2일', '2026-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (134, '불교 경전템플스테이', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/2/26/20260226085459263_1_S.webp', '불교경전이나 논서를 공부하며 휴식하는 템플스테이.', '1일차;11:00~12:00 경전공부;12:00~13:30 점심공양 및 휴식;13:30~15:00 경전공부', '당일형 프로그램의 경우 별도의 준비물이 필요없습니다. 개인물병정도 준비하시면 됩니다.', 40000, '당일', '2026-02-01', '2026-12-31', 20, FALSE, 0, 0),
    (135, '청산에서 힐링을~ (휴식형)', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_25573_S.webp', '장육사는 나옹스님이 창건한 사찰입니다. 장육사 템플스테이에서는 나옹스님께서 남기신 유명한 청산가 가사처럼, 자연 그대로를 바라보고 느끼는 시간을 갖도록 휴식형 힐링 프로그램을 준비했습니다. 산과 물과 바람과 창공의 청명함 속에서 비구니 스님이 직접 차려주시는 소박하고 담백한 사찰음식으로 나를 맑히는 소중한 시간을 보내시길 바랍니다. ''청산에서 힐링을~'' 프로그램은 남녀노소 누구나 참여 가능합니다.', '1일차;15:00~15:30 도착 및 방사배정;15:30~16:30 사찰예절 및 안내;17:00~17:30 저녁공양;18:00~18:40 범종체험 및 예불(자율);19:00~20:00 108배 및 별보기 명상(자율);21:00~04:20 취침;2일차;04:20~04:30 기상 및 예불준비;04:30~06:00 새벽예불 및 자율참선;07:00~07:30 아침공양;08:00~09:00 운서산 선명상길 포행;09:00~10:00 스님과의 차담;10:00~10:30 방사 및 주변 정리;10:30~11:00 집으로', '수건, 칫솔, 개인 세면도구, 양말(법당 출입시 반드시), 개인물병, 편한 신발(운동화) 등 (동절기에는 개인 방한 용품 준비)', 80000, '1박 2일', '2026-02-01', '2026-12-31', 20, FALSE, 0, 0),
    (136, '[선명상] "내안에 나를 마주하다" 전등사 "맞-선" 템플스테이(명상+하타요가)[전등각 한옥 독채]', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/8/11/20250811055132697_1_S.webp', '1700년 한국불교의 전통 수행인 선(禪)을 통하여 바쁜 일상을 사는 현대인들이 생활속에서 나이,종교를 떠나 누구나 쉽게 수행할 수 있도록 선명상 템플스테이를 진행합니다. 맞-선 템플스테이는 명상,요가,차담 등 다양한 프로그램을 통해 지쳤던 일상을 벗어나 내 안에 "나를 마주할 수" 있는 시간을 제공하고자 합니다. 방사는 전등각 한옥 독채 옵션입니다.', '1일차;13:30~14:00 사찰도착 및 방사 배정;15:40~16:00 일정안내;16:00~17:00 사찰안내 및 사찰예절습의;17:00~17:30 저녁공양;17:50~18:10 사물의식(타종체험);18:10~18:30 저녁 예불;18:45~19:30 선명상;19:30~20:00 108배;21:00~04:00 세면 및 취침;2일차;04:00~04:30 도량석;04:30~05:00 새벽 예불;06:00~06:55 발우 공양;07:00~07:30 운력;08:00~10:00 몸과 마음을 알아차리는 하타요가;10:00~10:50 방청소 및 수련복, 시트 반납;11:00~11:30 일요법회;11:30~12:00 점심공양;12:00~12:30 회향', '개인 티셔츠(민소매 불가, 조끼/바지는 지급), 개인 칫솔·수건(샴푸·린스·비누·치약·드라이기 비치), 여벌 속옷과 양말, 운동화(슬리퍼 불가), 개인 물병, 작은 우산, 긴팔 옷, 배낭(캐리어 불가)', 200000, '1박 2일', '2026-03-01', '2026-10-18', 20, FALSE, 0, 0),
    (136, '[선명상] "내안에 나를 마주하다" 전등사 "맞-선" 템플스테이(명상+하타요가)[취향당-개별화장실/샤워부스]', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/7/2/20250702042613634_1_S.webp', '1700년 한국불교의 전통 수행인 선(禪)을 통하여 바쁜 일상을 사는 현대인들이 생활속에서 나이,종교를 떠나 누구나 쉽게 수행할 수 있도록 선명상 템플스테이를 진행합니다. 맞-선 템플스테이는 명상,요가,차담 등 다양한 프로그램을 통해 지쳤던 일상을 벗어나 내 안에 "나를 마주할 수" 있는 시간을 제공하고자 합니다. 방사는 취향당(개별화장실/샤워부스) 옵션입니다.', '1일차;13:30~14:00 사찰도착 및 방사 배정;15:40~16:00 일정안내;16:00~17:00 사찰안내 및 사찰예절습의;17:00~17:30 저녁공양;17:50~18:10 사물의식(타종체험);18:10~18:30 저녁 예불;18:45~19:30 선명상;19:30~20:00 108배;21:00~04:00 세면 및 취침;2일차;04:00~04:30 도량석;04:30~05:00 새벽 예불;06:00~06:55 발우 공양;07:00~07:30 운력;08:00~10:00 몸과 마음을 알아차리는 하타요가;10:00~10:50 방청소 및 수련복, 시트 반납;11:00~11:30 일요법회;11:30~12:00 점심공양;12:00~12:30 회향', '개인 티셔츠(민소매 불가, 조끼/바지는 지급), 개인 칫솔·수건(샴푸·린스·비누·치약·드라이기 비치), 여벌 속옷과 양말, 운동화(슬리퍼 불가), 개인 물병, 작은 우산, 긴팔 옷, 배낭(캐리어 불가)', 100000, '1박 2일', '2026-03-01', '2026-10-18', 20, FALSE, 0, 0),
    (136, '[선명상] "내안에 나를 마주하다" 전등사 "맞-선" 템플스테이(명상+하타요가)[월송요-개별화장실/샤워부스]', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_25198_S.webp', '1700년 한국불교의 전통 수행인 선(禪)을 통하여 바쁜 일상을 사는 현대인들이 생활속에서 나이,종교를 떠나 누구나 쉽게 수행할 수 있도록 선명상 템플스테이를 진행합니다. 맞-선 템플스테이는 명상,요가,차담 등 다양한 프로그램을 통해 지쳤던 일상을 벗어나 내 안에 "나를 마주할 수" 있는 시간을 제공하고자 합니다. 방사는 월송요(개별화장실/샤워부스) 옵션입니다.', '1일차;13:30~14:00 사찰도착 및 방사 배정;15:40~16:00 일정안내;16:00~17:00 사찰안내 및 사찰예절습의;17:00~17:30 저녁공양;17:50~18:10 사물의식(타종체험);18:10~18:30 저녁 예불;18:45~19:30 선명상;19:30~20:00 108배;21:00~04:00 세면 및 취침;2일차;04:00~04:30 도량석;04:30~05:00 새벽 예불;06:00~06:55 발우 공양;07:00~07:30 운력;08:00~10:00 몸과 마음을 알아차리는 하타요가;10:00~10:50 방청소 및 수련복, 시트 반납;11:00~11:30 일요법회;11:30~12:00 점심공양;12:00~12:30 회향', '개인 티셔츠(민소매 불가, 조끼/바지는 지급), 개인 칫솔·수건(샴푸·린스·비누·치약·드라이기 비치), 여벌 속옷과 양말, 운동화(슬리퍼 불가), 개인 물병, 작은 우산, 긴팔 옷, 배낭(캐리어 불가)', 120000, '1박 2일', '2026-02-14', '2026-10-31', 20, FALSE, 0, 0),
    (136, '몸과 마음을 알아차리는 하타요가(Hatha Yoga)수행', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_25198_S.webp', '하타 요가는 동작의 빠름과 느림 , 머무름과 움직임 등을 골고루 사용하여 몸과 마음을 알아차리게 도와주는 수련법으로 스스로를 관찰하며 몸의 모든 부위를 골고루 사용하여 근력과 유연성을 길러주고 몸과 마음을 가볍고 단단하게 합니다. 여러 가지 신체적인 동작요가의 다양한 자세로 신체의 좌우, 상하균형을 맞추는 아사나 (Asana) 수행으로 몸과 마음, 그리고 영혼을 일깨우는 통합적이고 완벽한 경험을 하게 될 것입니다. 각자의 포지션에 맞게, 각기 다른 능력, 연령, 신체적 조건에 적합하게 수련 지도를 받게 될 것이며, 수련생들이 단계에 따라 초급, 중급, 고급으로 나뉘어 고전요가보다 쉽게 효과적으로 수행할 수 있게될것입니다. 다만, 여러종류의 질병 치료와 예방을 위해 조화력과 균형능력을 높이는 신체 수행으로 불완전한 육체를 회복하는 아사나(Asana)에 집중할 수 있게 주의 사항을 잘 숙지하시기 바랍니다.

1. 수련시간은 2시간이며, 오전6시50분에 시작합니다. 5분前(전)에 선불장으로 오셔서 사바사나(송장자세) 요가매트를 깔고 누워 계세요.
2. 6시에 시작하는 아침공양시간에 간단한 누룽지 또는 야채와 과일 한 조각 등 가벼운 식사를 권합니다. (금식하면 더 좋습니다)
3. 수련 중에 묵언 - 자신의 몸에 집중해서 내면의 평화를 찾아야 합니다.
4. 개인수건 준비
5. 요가수련 전날 자극적인 음식, 고기, 튀김음식, 술, 담배, 과음, 과식을 금합니다.

* 상기 참가비는 주중 휴식형 템플스테이 참가자분들에게 적용되는 금액입니다.
당일 요가만 참석하시는 분들은 참가비 50,000원입니다.', '1일차;06:50~09:00 몸과 마음을 알아차리는 하타요가(Hatha Yoga)수행', '1. 요가에 적합한 편한 복장
2. 개인수건', 30000, '당일', '2026-03-01', '2026-10-31', 20, FALSE, 0, 0),
