◆ 방사 배정 관련◆

체험형 템플스테이는 적정인원 참여를 위해 같은 성별인 타인과 방사를 함께 사용하게 됩니다.

예약순으로 3인실(2~3인 사용) 또는 6인실(4~6인 사용) 배정되오니 참고 바랍니다.

가족 또는 일행과 같은 방으로 배정해드리며, 가족이라도 성별에 따라 따로 방을 배정합니다. (예외: 부모와 미성년 자녀)

