    (146, '[개별신청] 내가 먹은 음식이 내 몸과 인격을 만든다', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_2121_S.webp', '"내가 먹은 음식이 내 몸과 인격을 만든다." 천년고찰이며, 사찰음식의 명소인 진관사에서 사찰음식을 맛볼 수 있는 기회를 마련했습니다. 현대화시킨 발우공양으로 조금 편안하게 접근하고, 집에 가서도 시도할 수 있길 바라는 마음으로 준비합니다. 나의 몸과 환경을 모두 살리는 발우공양은 묵언으로 진행합니다. 
