    (147, '노고단을 그대품안에', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/6/16/20260616033849142_1_S.webp', '노고단에 올라 지리산의 정기를 받아 재충전 하는 시간. 차량 운행 프로그램으로 성삼재까지 데려다 드리고, 하산 후 다시 천은사까지 운행합니다. 국립공원 노고단 탐방로 예약은 직접 해야 합니다. 주말은 월 1회만 운영합니다(천재지변·기상 상황에 따른 탐방로 통제시 휴식형으로 전환되며 차액 환불).', '1일차;15:00~15:30 입소 및 방사배치;17:00~17:30 사찰 안내 및 습의 안내;17:30 저녁 공양;18:00~18:10 타종;21:00 취침;2일차;05:00~05:30 새벽예불(자율);06:30~07:00 침구류·수련복 반납;07:00 아침 공양;07:30~11:00 성삼재 이동 후 노고단 산행;11:00~11:30 주차장 집결 후 천은사 이동;11:30~12:00 방사 정리 후 퇴소;12:00 점심 공양', '각 방 기본 시설(에어컨/선풍기, 샤워시설, 침대 또는 매트리스, 치약·비누·휴지·드라이기, 인터넷). 수련복 지급. 개인 준비물: 세면도구 및 수건, 편안한 옷 및 신발(운동화), 개인 물병, 양말.', 120000, '1박 2일', '2026-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (147, '산사에서 나를 만나다 [휴식형]', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/9/7/20260907114252839_1_S.webp', '각자의 자리에서 살아온 우리가 잠시 같은 공간에 머물며 인연을 나눕니다. 스쳐가는 만남일지라도 함께 머문 고요한 시간이 서로의 마음에 오래 남습니다. 신청 인원에 맞춰 방사가 배정되며 객실 정원에 따라 다른 참가자와 함께 방사를 사용할 수 있습니다. 1인실은 수량 한정, 선착순 운영.', '1일차;15:00~15:30 입소 및 방사 배정;17:00~17:30 사찰 안내 및 습의 안내;17:30 저녁 공양;18:00~18:10 타종;21:00 취침;2일차;07:00~07:20 아침 공양;07:20~08:00 지리산 걷기 명상;08:30~09:00 차담;09:00~09:30 후기 작성;09:30~10:00 방사 정리, 세탁물 반납;11:00 아름다운 마무리(퇴소)', '각 방 기본 시설(에어컨/선풍기, 샤워시설, 침대 또는 매트리스, 치약·비누·휴지·드라이기, 인터넷). 수련복 지급. 개인 준비물: 샴푸·린스·세면도구 및 수건, 편안한 옷 및 신발(운동화), 개인 물병, 양말.', 80000, '1박 2일', '2026-09-07', '2026-12-31', 20, FALSE, 0, 0),
    (147, '오늘은 특별히 [독채]', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_29472_S.webp', '고승들의 결기가 서린 천은사 계곡은 오늘도 굽이치며 차갑게 흐르고, 새벽 도량석 소리는 억겁의 시간 치달려온 집 짓는 자의 어둠을 깨운다. 서래당은 천은사 계곡과 방장 선원 사이에 위치하여 고요하고 생명력이 가득한 독채 휴식 공간입니다. 기준 2인/최대 3인, 4인 이상·당일 예약·일주일 이상 예약은 전화 문의.', '1일차;15:00~15:30 입소 및 방사 배정;17:00~17:30 사찰 안내 및 습의 안내(탄력적 진행);17:30 저녁 공양;18:00~18:10 타종;21:00 취침;2일차;07:00~07:20 아침 공양;07:20~08:00 지리산 걷기 명상;08:00~09:00 차담;09:00~09:30 후기 작성;09:30~10:00 방사 정리;11:00 아름다운 마무리(퇴소)', '기본 시설(에어컨/선풍기, 샤워시설, 침대(K,SS), 치약·비누·휴지·드라이기, 인터넷). 수련복 지급(조끼 또는 티셔츠와 바지). 추가시설: TV, 커피포트, 냉장고, 4인용 테이블, 비데. 개인 준비물: 샴푸·린스·세면도구 및 수건, 편안한 옷 및 신발, 개인 물병, 양말.', 350000, '1박 2일', '2025-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (147, '지금은 가만히 [능엄]', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_29443_S.webp', '온몸을 감싸는 숲의 숨결. 청명한 하늘과 잔잔한 풀벌레 소리, 숲 내음과 산산한 바람, 총총한 밤하늘의 별, 이것만으로 충분하다. 최대 2인 사용 가능.', '1일차;15:00~15:30 입소 및 방사 배정;17:00~17:30 사찰 안내 및 습의 안내(탄력적 진행);17:30 저녁 공양;18:00~18:10 타종;21:00 취침;2일차;07:00~07:20 아침 공양;07:20~08:00 지리산 걷기 명상;08:00~09:00 차담;09:00~09:30 후기 작성;09:30~10:00 방사 정리;11:00 아름다운 마무리(퇴소)', '기본 시설(에어컨/선풍기, 샤워시설, 침대(Q), 치약·비누·휴지·드라이기, 인터넷). 수련복 지급. 추가시설: 안마의자, TV, 커피포트, 냉장고. 개인 준비물: 샴푸·린스·세면도구 및 수건, 편안한 옷 및 신발, 개인 물병, 양말.', 150000, '1박 2일', '2025-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (147, '비움과 채움 [체험형]', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/6/17/20260617090914634_1_S.webp', '🍀비움과 채움 템플스테이🍀

지리산 천은사에서 걱정은 내려놓고 마음은 채워가는 1박 2일.

숲길 포행과 명상, 타종체험, 합장주 만들기, 새벽예불과 108배, 그리고 미래의 나에게 보내는 편지까지.

바쁜 일상 속 잠시 멈춰 서서 온전히 나를 돌아보는 시간을 만나보세요.

"걱정은 내려놓고, 마음은 채워갑니다."

▷ 예약 진행 과정 : 신청 > 입금 > 예약확정

＊2일 이내 확정 후 별도 문자 드립니다.

▷ 예약 : 전화 예약 및 현장 접수 불가.

▷ 입금 : 예약 후 입금자 순으로 승인되므로, 바로 입금 바랍니다.

1인실 옵션 추가 *필수*

1인실 미선택시 타인과 함께 방을 사용 할 수 있습니다.

※ 일행끼리 방 배정을 하고 있으나, 한명인데 1인실 미선택 인원끼리는 한방을 쓸 수 있습니다.

❗15시 이후 입소 불가❗

당일 취소 처리 되어 환불은 불가 합니다.

사정이 부득이한 경우 연락 주세요.

※ 일정은 사정에 따라 변동 될 수 있으며, 프로그램 참여는 자율 입니다.', '1일차;15:00~15:30 입소 방사배정;15:30~16:00 습의안내;16:00~17:00 108배 , 합장주 만들기;17:30~18:00 저녁 공양;18:00~18:30 사물 체험;21:00~00:00 취침;2일차;05:00~06:00 새벽 예불;07:00~07:20 아침 공양;07:20~08:00 지리산 걷기 명상;08:30~09:30 차담;09:30~10:00 소감문 작성 및 방사 정리;11:00~00:00 아름다운 마무리 (퇴소)', '▷ 각 방 기본 시설

