    (148, '[체험형/휴식형] 자연에서 나를 찾고, 나를 알고, 나를 본다. 서울 도봉산 천축사 고!고! (체험형, 휴식형은 프로그램 참여 선택 가능)', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/2/23/20260223100017337_1_S.webp', '하늘 아래 신선대에서 신선이 되어 보세요. 천년기도도량의 깊은 역사와 문화의 숨결이 가득한 천축사에서 참가자의 일상에서 지친 몸과 마음을 재충전하는 프로그램. 한국어가 어려운 외국인은 통역 가능한 사람과 동참 필요. 안내 문자는 매주 월요일 발송.', '1일차;13:00~14:00 참가자 방배정, 입실 완료;15:30~16:30 참가자 OT(대웅전);17:00~18:00 저녁 공양;18:00~19:00 스님과 차담(자율참가);19:00~20:00 염주만들기;20:00~21:00 자유시간(산사 야경);21:00~05:00 무문관 사용(묵언, 세면, 취침);2일차;05:30~06:30 아침 예불(자유참가);07:00~07:30 아침 공양;07:30~08:00 일출 감상;08:00~09:00 108배;09:00~10:00 소감문 작성 후 퇴소', '수련복(바지·조끼)과 고무신은 사중 제공(겨울엔 운동화 권장). 개인 준비물: 수건·치약·칫솔·샴푸·린스·비누 등, 휴대용 개인물통(컵) 필수, 운동화 또는 등산화 필수, 따뜻한 옷과 여벌 옷, 겨울철 스틱·아이젠 권장.', 80000, '1박 2일', '2026-01-03', '2026-11-30', 20, FALSE, 0, 0),
    (149, '청계水에 茶를 우리다', '휴식형', 'https://ts-cdn.com/ups/templePrg/2025/3/2/20250302032136532_2_S.webp', '휴식!!! 그 위대한 시간을 마술처럼 쓰는 공간, 청계수에 우린 달콤씁쓰래한 녹차가 주는 위안을 지리산이 품은 넉넉하고 맑은 에너지가 주는 힐링을 체험. 옛부터 아토피, 위장장애 등 치유 이야기가 전해지는 청계약수를 맛보고, 지리산 자락의 편백과 대나무 숲에서 걸러진 천연의 맑은 공기에 몸과 마음을 힐링하며 자신만의 시간을 갖는 프로그램. (하동군 소재 청계사)', '1일차;15:30~16:00 사찰도착,방배정,수련복착복;16:00~16:30 오리엔테이션 및 사찰안내;18:00~18:30 저녁공양(여름);19:00~19:30 저녁예불;19:30~21:00 자유시간(마당에 누워 별보기 등);21:00 취침;2일차;05:00~05:30 새벽예불;06:00~06:30 아침공양;08:00~09:00 자유시간(산책, 대나무숲 치유);09:00~10:00 스님과 차담, 차명상;10:30~11:00 소감문 작성, 퇴실준비;11:30~12:00 점심공양 후 퇴실', '수련복(조끼와 바지) 지급. 개인 세면도구, 수건, 칫솔, 여벌옷, 운동화, 양말, 개인물병, 우산. 샴푸·린스·드라이기는 미비치.', 60000, '1박 2일', '2025-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (149, '"선명상" 템플스테이(1박2일형)', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/9/25/20250925042523053_1_S.webp', '비오는 날 문득 소리를 듣는 나를 듣는다. 햇빛 좋은 봄날에 찬란한 해를 마주보는 나를 본다. 새벽하늘 그곳에서 총총한 별빛을 호흡하는 날것의 "나"를 있는 그대로 숨쉬고 내쉰다. "선명상"을 통해 더욱 맑게 밝게 장엄해보자. 108배 명상, 선명상, 자비명상, 명종(싱잉볼) 각성 명상, 단주만들기 등. 1인 예약은 1인실 사용비 2만원 추가.', '1일차;15:30~16:00 사찰도착,방배정,수련복착복;16:00~16:30 오리엔테이션 및 사찰안내;18:00~18:30 저녁공양(여름);19:00~19:30 저녁예불;19:30~21:00 자유시간;21:00 취침;2일차;05:00~05:30 새벽예불;06:00~06:30 아침공양;08:00~09:00 자유시간;09:00~10:00 스님과 차담, 차명상;10:30~11:00 소감문 작성, 퇴실준비;11:30~12:00 점심공양 후 퇴실', '수련복(조끼와 바지) 지급. 개인 세면도구, 수건, 칫솔, 여벌옷, 운동화, 양말, 개인물병, 우산. 샴푸·린스·드라이기 미비치.', 70000, '1박 2일', '2024-10-24', '2026-12-31', 20, FALSE, 0, 0),
    (149, '잠시 머물고 간 산사에서 "나"를 돌아 보다(당일형)', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/6/25/20260625090246974_1_S.webp', '끊임없이 반복되는 일상속에서 잠시나마 벗어나 스스로에게 선물하는 작은 행복...

