    (150, '계정혜 입문_1박2일', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/6/8/20260608090834866_1_S.webp', '청량사는 산중에 자리한 사찰로, 프로그램도 단순한 체험이나 휴식 중심이 아니라 사찰에서 생활하며 정해진 수행 일정에 직접 참여하는 방식으로 진행됩니다. 입문형은 수행을 처음 접하는 분을 위한 단계로, 출가오계를 처음 접하는 분들을 위한 입문 과정입니다. 예약 전 반드시 문자(SMS)로 먼저 연락(010-2683-6704) 필요.', '1일차;15:00 도착 및 방 배정;15:00~15:30 템플복 착용 및 시설 안내;15:30~16:00 오리엔테이션;16:00~17:00 출가오계 설명 및 수계식;17:00~17:30 사물 체험;17:30~18:00 오후 절제(떡·과일);18:25~18:50 사물 관전 및 자비관 명상;18:55~19:15 저녁 예불 동참;19:20~20:00 낭독 108배;20:00~21:20 스님과 차담;21:20~21:40 탑전 별 보기;21:40 취침;2일차;04:00~04:30 도량석;04:50~05:15 새벽 예불;05:15~06:10 스트레칭+명상(선택);06:30~07:30 아침공양(죽);07:30~08:30 운력;08:30~11:30 오전 자유 수행(선택) 및 방사정리;11:30~12:30 점심공양;12:30~13:30 스님과 소감 나눔;14:00 퇴실', '치약은 사찰 비치. 칫솔, 수건, 개인수건, 물통(텀블러) 필수. 편안한 복장, 운동화·양말(민소매·반바지 불가). 개인상비약. 얇은 겉옷(산중 일교차 대비). 수련복은 조끼만 지급.', 70000, '1박 2일', '2026-06-15', '2026-12-31', 20, FALSE, 0, 0),
    (150, '계정혜 체험_1박2일', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/6/9/20260609011030413_1_S.webp', '청량사는 산중에 자리한 사찰로, 사찰에서 생활하며 정해진 수행 일정에 직접 참여하는 방식으로 진행됩니다. 계정혜 체험은 팔관재계를 유연하게 수지하며 수행의 깊이를 경험하는 과정입니다. 오후에는 떡과 과일로 단출하게 절제하며 청정한 하루를 보냅니다. 예약 전 반드시 문자(SMS)로 먼저 연락(010-2683-6704) 필요.', '1일차;15:00 도착 및 방 배정;15:00~15:30 템플복 착용 및 시설 안내;15:30~16:00 오리엔테이션;16:00~17:00 팔관재계 설명 및 수계식;17:00~17:30 사물 체험;17:30~18:00 오후 절제(떡·과일);18:25~18:50 사물 관전 및 자비관 명상;18:55~19:15 저녁 예불 동참;19:20~20:00 낭독 108배;20:00~21:20 스님과 차담;21:20~21:40 탑전 별 보기;21:40 취침;2일차;04:00~04:30 도량석;04:50~05:15 새벽 예불;05:15~06:10 스트레칭+명상(선택);06:30~07:30 아침공양(죽);07:30~08:30 운력;08:30~11:30 오전 자유 수행(선택) 및 방사정리;11:30~12:30 점심공양;12:30~13:30 스님과 소감 나눔;14:00 퇴실', '치약은 사찰 비치. 칫솔, 수건, 개인수건, 물통(텀블러) 필수. 편안한 복장, 운동화·양말(민소매·반바지 불가). 개인상비약. 얇은 겉옷. 수련복은 조끼만 지급.', 90000, '1박 2일', '2026-06-15', '2026-12-31', 20, FALSE, 0, 0),
    (150, '계정혜 정진_1박2일', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/6/10/20260610082936649_1_S.webp', '보다 진지하고 깊이 있는 수행을 원하시는 분께 권해 드리는 프로그램입니다. 팔관재계 여덟 가지를 모두 완전히 수지하며, 오후에는 일체 음식을 드시지 않습니다. 참여 희망자는 프로그램 내용을 모두 읽고 확인 후 예약 전 반드시 전화(010-2683-6704)로 연락 필요.', '1일차;15:00 도착 및 방 배정;15:00~15:30 템플복 착용 및 시설 안내;15:30~16:00 오리엔테이션;16:00~17:30 팔관재계 설명 및 수계식(오후 불식 서약);17:30~18:00 사물 체험;18:25~18:50 사물 관전 및 자비관 명상;18:55~19:15 저녁 예불 동참;19:20~20:00 낭독 108배;20:00~21:20 스님과 차담;21:20~21:40 탑전 별 보기;21:40 취침;2일차;04:00~04:30 도량석;04:50~05:15 새벽 예불;05:15~06:10 스트레칭+명상(선택);06:30~07:30 아침공양(죽);07:30~08:30 운력;08:30~11:30 오전 자유 수행(선택) 및 방사정리;11:30~12:30 점심공양;12:30~13:30 스님과 소감 나눔;14:00 퇴실', '치약은 사찰 비치. 칫솔, 수건, 개인수건, 물통(텀블러) 필수. 편안한 복장, 운동화·양말(민소매·반바지 불가). 개인상비약. 얇은 겉옷. 수련복은 조끼만 지급.', 100000, '1박 2일', '2026-06-15', '2026-12-31', 20, FALSE, 0, 0),
    (151, '무위 캠핑스테이 : 無爲 Camping Stay', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/4/5/20260405053517030_5_S.webp', '아무것도 하지 않는 시간, 그 자체로 충분한 머묾. 고려산 자락 청련사에서 자연 속에 머물며 나를 내려놓는 시간을 경험하는, 정해진 프로그램을 따라가지 않는 수행형 캠핑스테이. 텐트에서 머물며 사찰의 하루 흐름에 조용히 함께함. 텐트 및 캠핑 장비는 개인 준비(백패커형 캠핑).', '1일차;14:30~16:30 도착 및 텐트 설치;16:30~17:30 사찰 안내 및 예절 교육;17:30~18:30 저녁공양;18:30~21:00 자유시간(산책, 명상, 휴식);21:00~21:30 취침 준비;2일차;07:30~08:00 아침공양;08:00~10:30 자유시간(운력, 트래킹, 명상, 휴식);10:30~11:30 텐트 정리 및 주변 정리;11:30~12:00 체험 소감문 작성;12:00~12:30 집으로', '텐트, 팩/팩망치, 침낭 또는 이불, 매트/에어매트(필수), 랜턴/헤드랜턴, 보조배터리, 긴팔 옷, 여벌 옷, 양말, 운동화, 개인 물병, 캠핑용 물티슈(샤워 대체), 개인 상비약, 이어플러그 등.', 45000, '1박 2일', '2026-04-05', '2026-12-31', 20, FALSE, 0, 0),
    (151, '[움직이는 명상 선무도_ 禪武道]', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/6/26/20260626031648991_1_S.webp', '[움직이는 명상 선무도_ 禪武道]
"몸을 움직여 마음을 깨우다"

• 선무도(禪武道)는 몸과 마음을 함께 수련하는 한국의 전통 수행법입니다.
• 가벼운 스트레칭부터 호흡, 선무도 기본 동작, 명상까지 누구나 쉽고 편안하게 참여할 수 있습니다.


♦이런 분께 추천♦
• 몸이 뻣뻣하고 피로가 쌓인 분
• 스트레스와 긴장을 내려놓고 싶은 분
• 운동과 명상을 함께 배우고 싶은 분
• 몸과 마음을 건강하게 회복하고 싶은 분


