    (152, '휴식형 템플스테이 ''나를 위한 쉼표,''', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_23946_S.webp', '나를 위한 쉼표, 아름다운 소양호와 신령스런 오봉산의 정기로 천년의 숨결을 간직한 청평사. 고즈넉한 산사가 주는 평온한 마음, 청량하고 맑은 공기, 아름다운 별빛과 달빛을 벗 삼을 수 있는 곳. 아름다운 자연·역사·문화가 살아있는 산사에서 자신의 진정한 아름다움을 발견하고 소통을 통해 관계를 회복하는 행복여행.', '1일차;15:00~16:00 어서오세요~;16:30~17:20 사찰예절습의;17:30~18:00 저녁 공양;18:30~19:00 저녁 예불(자율선택);19:00~19:40 108배(자율선택);21:00 취침;2일차;04:30~05:00 새벽 예불(자율선택);07:00~07:30 아침 공양;10:00~11:00 소감문 작성 및 방사 정리;11:00 또 만나요~(퇴소)', '참가복(조끼) 제공. 세면도구(수건 포함). 여름철 반팔티셔츠 필수(민소매 불가). 겨울철 방한용품 권장. 양말, 운동화(맨발 불가). 개인물병 필수. 개인용품(여성용품), 개인 비상약품. 우산 등.', 60000, '1박 2일', '2026-09-01', '2026-10-31', 20, FALSE, 0, 0),
    (152, '체험형 템플스테이 ''천년의 숨결''', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_23954_S.webp', '명상하기 좋은 곳, 청평사와 더불어 명상을 알고자 하는 이들과의 소통하고 호흡명상을 기반으로 걷기 명상, 차 명상 등 다양한 명상법을 체험 할 수 있습니다. 아름다운 소양호과 신령스런 오봉산의 정기로 천년의 숨결을 간직한 청평사 고즈넉한 산사가 주는 평온한 마음 청량하고 맑은 공기, 아름다운 별빛, 달빛과 벗 삼을 수 있는 곳 신비스러운 이야기를 품은 아름다운 곳 아름다운 자연, 역사, 문화가 살아있는 산사에서 자신의 진정한 아름다움을 발견하고 소통을 통해 관계를 회복하는 단 하나의 행복여행, 휴식과 힐링이 필요한 당신이 행복해 질 수 있는 곳 청평사로 초대합니다.', '1일차;15:00~15:30 도착 및 방사 배정;15:30~16:20 스트레칭 / 명상;16:30~17:20 사찰예절 습의;17:30~18:20 저녁 공양;18:30~19:00 저녁 예불;19:00~19:40 행복을 찾는 108배;20:00~21:00 쉼 / 명상 ( 자율 );21:00~21:30 세면 및 취침;2일차;04:30~05:00 새벽 예불 ( 자율 선택 );05:00~07:00 쉼 / 명상 ( 자율 );07:00~08:00 아침 공양;09:00~10:00 스트레칭 / 명상;10:00~10:40 차담 ( 마음 나누기 );10:40~11:00 소감문 작성;11:00~11:30 방사 정리 및 집으로', '▶캐리어는 자제해 주시기 바랍니다. 참가복으로 조끼만 드립니다.(템플에 머무시는 동안 참가복 착용) ▶세면도구(수건 포함) ▶여름철 반팔티셔츠 필수(민소매는 안됩니다.) ▶겨울철에는 따뜻한 방한용품 챙겨오시는걸 추천드립니다. ▶양말(맨발 불가), 운동화 ▶개인물병 필수지참 ▶개인용품(여성용품), 개인 비상약품 ▶날씨에 따른 개인 용품(긴팔옷, 우산 등) ▶비누, 치약 구비되어 있습니다.', 80000, '1박 2일', '2026-05-01', '2026-10-31', 20, FALSE, 0, 0),
    (153, '쉼 템플스테이 (휴식형)', '휴식형', 'https://ts-cdn.com/ups/templePrg/2026/3/17/20260317035551681_1_S.webp', '축서사 자유로운 휴식 템플스테이는 사람과 자연의 태고적 신비한 기운을 고스란히 간직한 청정수행도량에서 바쁜 일상을 잠시 내려놓고 오롯이 자신만을 위한 시간을 가지며 몸과 마음을 편안하게 쉬는 프로그램입니다. 문수산 750고지에서 팔을 뻗으면 구름이 손에 잡히고, 바람도 한가로이 머물다 가는 곳! 수려한 경관의 축서사에서 휴식을 취하며, 자유롭게 기도하고 수행하면서 홀가분하게 내면으로 향할 수 있습니다. 입산 시간과 공양 시간만 지키고 그 외는 자율적으로 휴식을 하며, 고요한 산사에서 자신을 힐링하는 프로그램입니다.', '1일차;15:00~16:00 입산 및 방사 배정;16:30~17:10 사찰 투어;17:30~18:00 저녁 공양;19:00~20:00 저녁 예불(선택);20:00~03:00 휴식 및 취침;2일차;04:40~05:40 새벽 예불 및 108배(선택);06:00~06:30 아침 공양;07:00~09:00 포행 및 휴식;09:00~10:00 스님과의 차담;10:10~10:30 방사 정리 후 회향', '개인 세면도구, 수건, 칫솔, 여벌 옷, 운동화(편한 신발), 양말, 개인(보온) 물통(컵) * 동절기: 추위 대비 외투, 내의, 덧신, 무릎 담요, 방한 용품', 50000, '1박 2일', '2025-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (154, '통도사 품에 안기다', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_13115_S.webp', '통도사 템플스테이는 휴식형과 체험형으로 구분이 됩니다. 휴식형은 프로그램 일정 없이 휴식을 하시고자 하는 분들에게 추천해드립니다.

체험형은 매월 1회 또는 2회 진행이 되지만, 사중일정으로 인해 진행이 되지 않는 경우도 있습니다.

체험형은 직장인, 일반인 등 개개인이 모여 단체 프로그램을 수행하는 유형이며, 시작부터 끝까지 스님과 동반하여 진행이 됩니다.

체험형의 경우 선착순으로 예약이 마감되오니 참고하시기 바랍니다. 예약을 하실 땐 입금을 해주셔야 예약완료가 되며 (3일안에 미입금시 취소처리 됩니다), 예약완료후 취소 시 꼭 취소신청 또는 전화연락 부탁드립니다.

(단 예약 인원이 20명 미만일시 일정이 취소될수도있습니다)

잠시만이라도 일상에서 받고 있는 스트레스를 잊고, 잠시만이라도 오직 나만을 위한 시간을 갖고, 잠시만이라도 내 마음을 어디에 두고 있는지 알아가며, 잠시만이라도 나의 마음을 다스려 보기 위한 기회가 여기 통도사에 있습니다.

※ 참가자는 중학생 ~ 70세까지 참가가 가능합니다. (20세미만은 부모님 동반하에 예약이 가능합니다)

※ 방은 남,여 구분하여 방을 사용합니다. 체험형은 예불참석, 공양, 운력, 보궁명상, 108배, 암자순례 등 사찰의 다양한 경험과 체험을 하실 수 있는 기회가 있습니다.', '1일차;13:30~14:00 도착/수련복지급;14:00~14:30 사찰예절 배우기;14:30~15:30 통도사 사찰안내;15:30~16:30 연꽃등만들기;17:00~18:00 저녁공양 및 휴식;18:30~19:30 사물관람 / 저녁예불/보궁참배;19:30~20:30 체험하기;20:00~21:00 세면 및 취침;2일차;04:00~04:20 일어나 세수하기;04:20~05:10 새벽예불;05:20~06:00 휴식;06:05~07:00 아침공양;07:00~08:30 암자순례;08:30~09:30 108염주 만들기 / 108배;09:30~10:00 주변정리, 방청소 / 회향(퇴실)', '※마스크(필수), 개인세면도구일체(수건), 운동화&등산화, 개인약, 개인컵, 편안한 개인 옷(외투,양말필수), 방한용품

※ 옷은 조끼와 바지가 지급이 됩니다 ※ ※ 방에는 침구 외에는 아무것도 준비되어 있지 않습니다

※ 세면장에도 아무것도 없으므로 수건, 드라이기를 따로 챙겨오셔야 합니다', 100000, '1박 2일', '2024-09-01', '2026-11-30', 20, FALSE, 0, 0),
