방사 신청시

* 사찰 내 방사는 남/녀  함께 머물 수 없음이 원칙입니다.

   (단, 부부+자녀 동반 예약시 제외 : 비고란에 "같은 방사 배정요청!")

* 예약후 24시간 이내 결제가 이루어지지 않을경우 자동 취소처리됩니다.

 구분 성인, 중/고, 초등, 체험형 1박(기본형)/ 120,000 / 60,000/ 40,000

* 휴식형,체험형(기본 방사 4인기준 배정)- "타인"과 함께 사용가능 하실 수 있으십니다.

 [[ 단, 가족, 친지, 친구 등 함께 이용시 "단독방 요청시 : 1인, 2인, 3인 사용시 추가비용 1박당 3만원 추가 발생!! ]]

  동반할 시 같은 방사를 원하실 경우 비고란에 ‘같은 방사 배정’ 이라고 표기해 주세요.

* 향일암은 가파른 산에 위치를 하고있습니다. ( 계단이 많다는 점!!!! - 캐리어 사용금지-파손위험 99% )

   평균 1박2일 이시므로 입실하실때, 최소 한의 짐을 챙겨서  백펙(배낭)을 이용하시는게 편합니다.

  동반할 시 같은 방사를 원하실 경우 비고란에 ‘같은 방사 배정’ 이라고 표기해 주세요.

* 자녀 동반 가족 경우, 비고란에 ‘가족’이라고 적어주시면, 같은 방사를 배정해 드립니다.

■ 입방은 15시입니다. 15시 30분을 넘어 오실 경우 도량안내를 받으실 수 없으며 17시 00분 이후 도착시 입실이 불가할 수도 있습니다.

■ 예약 취소나 환불의 경우, 문자메시지로 성함, 예약일, 입금하셨던 계좌번호와 예금주명 남겨주세요.

■ 만 70세 이상 어르신은 2인이상예약을 하셔야 예약이 접수됩니다.

