    (161, '해를 품은 향일암 기행[휴식형]', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_24981_S.webp', '해를 품은 향일암 템플스테이에서 지친 당신을 위한 시간을 가져보세요. 향일암은 "해를 바라보다"라는 뜻을 담고 있는 4대 관음성지 중 한 곳입니다. 7군데 바위 틈을 지나 일렁임 없는 먼 바다를 코 앞에서 만나게 되면 이보다 더한 곳은 없다는 탄성이 절로 나오는 곳입니다. 원효대사께서 관세음보살님을 접견하고 원통암(현향일암)을 창건하셨듯, 이 곳 향일암에서 일출을 보며 새로운 각오와 지친 맘을 모두 털어내고 그 빈 자리에 부처님의 가피를 가득 담아 가시길 바라는 프로그램입니다.

