    (164, '[체험형]오직 모를뿐 (1박2일)', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_24599_S.webp', '북한산 자락에 위치한 화계사에서 북한산 둘레길 걷기, 사찰투어, 예불, 명상체험, 108배와 염주만들기, 스님과의 차담 등을 통해 자신을 돌아보며 쉬어가는 체험형 템플스테이. 1박2일간의 일정으로만 참여 가능.', '1일차;13:30 도착 및 방배정;13:50 오리엔테이션 및 사찰안내;16:30 저녁 공양;17:40 타종 체험;18:00 저녁예불;18:20 108배, 108염주 만들기;21:00 취침;2일차;05:20 새벽예불;05:50 참선(자애 명상);06:30 아침 공양;09:30 스님과 차담;소감나누기;10:30 방정리후 귀가', '개인 세면도구, 수건(비누만 제공), 여벌 옷(외투), 양말, 운동화(편한 신발), 개인(보온) 물통, 개인 티셔츠(조끼 안에 받쳐 입을 것)', 90000, '1박 2일', '2026-05-01', '2026-12-31', 20, FALSE, 0, 0),
    (164, '오직 쉴뿐', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_26495_S.webp', '복잡하고 바쁜 일상을 떠나 화계사에서 여유롭게 휴식하며 지친 몸과 마음을 재충전하는 휴식형 템플스테이. 원할 경우 사전 신청으로 스님과의 차담 가능.', '1일차;13:30 도착 및 방배정;13:50 오리엔테이션;도량안내;16:30 저녁공양;18:00 저녁예불;21:00 취침;2일차;05:20 새벽예불;06:30 아침공양;09:30 스님과의 차담(사전 신청 시);10:30 방사정리 및 회향', '개인 티셔츠(조끼 안에 받쳐 입을 것), 개인 세면도구, 수건(비누만 제공), 여벌 옷(외투), 양말, 운동화(편한 신발), 개인(보온) 물통', 100000, '1박 2일', '2026-05-01', '2026-12-31', 20, FALSE, 0, 0),
    (164, '''선명상 템플스테이''_''일상생활속의 마음챙김''', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/4/8/20250408110632235_1_S.webp', '일상생활 속 마음챙김 명상을 주제로 한 선명상 특화 템플스테이. 명상, 미라클 모닝 명상, 숲길 산책, 차담 등으로 구성. 1박2일간의 일정으로만 참여 가능하며 매월 2~3회 진행.', '1일차;13:30 도착 및 방배정;14:00 오리엔테이션 및 도량안내;16:30 저녁공양;18:00 명상이란 무엇인가?;19:00 명상;21:00 소등 및 취침;2일차;05:20 예불;05:50 미라클 모닝 명상;06:30 아침공양;07:00 숲길 산책(자율);08:00 오늘의 명상;09:00 마음나누기 차담;11:00 방정리 및 회향', '개인 티셔츠(조끼 안에 받쳐 입을 것), 개인 세면도구, 수건(비누만 제공), 여벌 옷, 양말, 운동화(편한 신발), 개인 물통', 90000, '1박 2일', '2024-07-30', '2026-12-31', 20, FALSE, 0, 0),
    (164, '‘수요 머묾 템플스테이’', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/6/4/20260604013341901_1_S.webp', '바쁘게 흘러가는 한 주의 가운데,
잠시 마음을 내려놓고 천천히 머물러 보는 수요일.

‘수요 머묾 템플스테이 _ 손끝에 머무는 마음’은
사경과 만들기 체험을 통해
흩어진 마음을 차분히 모아가는 당일형 프로그램입니다.

한 글자 한 글자 정성을 담아 써 내려가고,
나만의 목탁을 만들며,
손끝에 집중하는 시간 속에서
어느새 마음도 함께 고요해집니다.

잘 만들어야 하는 체험이 아니라,
잠시 멈추어 나를 돌보는 시간.

바쁜 일상 속,
수요일 하루쯤은
내 마음에도 머물러 보세요.', '1일차;13:00~14:00 오리엔테이션 및 사찰 안내;14:00~15:00 사경 & 나만의 목탁 만들기;15:00~16:00 스님과의 차담', '"크게 준비하지 않아도 됩니다. 잠시 머무를 마음이면 충분합니다."', 40000, '당일', '2026-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (164, '''금요 쉼표 템플스테이''', '당일형', 'https://ts-cdn.com/ups/templePrg/2026/3/4/20260304104805964_1_S.webp', '"금요 쉼표 템플스테이" _ ''마음 머무는 금요일''

금요일 오후, 일상에 조용한 ''쉼표''를 찍어보세요.

금요 쉼표 템플스테이는 평일 오후, 비교적 한적한 시간에 진행되는 3시간 프로그램입니다.

스님과 함께 사찰을 천천히 걸으며 공간에 담긴 이야기를 듣고,
호흡에 집중하는 명상으로 마음을 고르게 한 뒤
따뜻한 차 한 잔과 함께 담담한 대화를 나눕니다.

주말을 앞둔 금요일, 서두르지 않고 잠시 머무는 시간.

일상 속에서 잠깐 방향을 고르는 작은 쉼표 같은 오후가 됩니다.', '1일차;13:00~14:00 오리엔테이션 및 사찰 안내;14:00~15:00 금요 쉼표 명상;15:00~16:00 스님과의 차담', '"크게 준비하지 않아도 됩니다. 잠시 머무를 마음이면 충분합니다."', 40000, '당일', '2026-01-01', '2026-12-31', 20, FALSE, 0, 0),
    (164, '‘화계사템플스테이’X‘역사문화 축제’', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/9/15/20260915125924549_1_S.webp', '축제와 함께, 화계사 하루

