    (165, '동해바다 위에 펼쳐지는 웰니스 요트명상', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/8/12/20260812043751433_1_S.webp', '현대 사회의 디지털 피로도 증가, 번아웃, 감정 소진 등의 문제 증가로 현대인들은 스트레스와 감정적 상처를 많이 겪게 됩니다. 이에 따라 자연 기반 치유프로그램에 대한 수요가 확대되고 있습니다. 우리 사찰에서는 이번 기회에 동해의 청정 자연환경과 사찰 수행 프로그램을 결합하여 차별화된 해양 명상 콘텐츠를 개발 제공함으로써 템플스테이의 가치를 증대하는데 앞장서고 지역 관광 및 웰니스 산업 활성화에 이바지하고자 합니다. 프로그램 구성: Calm Sailing(저속 항해를 통한 심리적 안정), 웰컴 드링크, 바다 위 명상(호흡/마음챙김), 오감만족 체험, 회향 및 성찰 시간.', '1일차;14:00~14:30 화암사 도착 및 방사 배정, 환복;14:30~15:20 [필수] 습의-입소 안내(자우당);15:30~17:00 [선택] 108배 염주꿰기 또는 사찰 안내;17:00~17:30 [필수] 저녁공양(공양간);18:00~19:00 [자율] 저녁 예불(대웅전);19:00~20:50 자유시간(포행, 별바라기, 독서, 야경 감상 등);21:00~22:00 취침;2일차;04:00~05:00 [선택] 새벽 예불(대웅전);05:00~06:30 [자율] 미륵전 해돋이 감상;06:30~07:00 [필수] 아침 공양;07:00~07:30 자유시간;07:30~08:30 요트장으로 이동(사찰버스);08:30~10:30 요트 명상;10:30~11:00 사찰로 복귀(사찰버스);11:00~11:30 퇴소 및 회향', '개인 세면도구(수건, 칫솔, 샴프, 머리빗 등), 운동화(편한 신발), 양말, 물병 등(헤어드라이기는 비치됨), 여벌 옷, 충전기, 간식거리 등 개인용품, 가능한 단정한 옷차림', 120000, '1박 2일', '2026-08-15', '2026-11-16', 20, FALSE, 0, 0),
    (165, '금강산 첫 시작(체험형)', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_9796_S.webp', '금강산 신선봉에서 나를 찾아가는 시간. 예불, 108배 염주 꿰기, 타종체험, 신선대 등반 및 미륵전 해맞이, 스님과의 차담, 수바위 등 숲길 포행, 공양 등 프로그램을 통해 행복한 삶을 찾아가도록 하는 프로그램입니다.', '1일차;14:00~14:30 화암사 도착, 숙소 안내 및 환복;14:30~15:20 습의-템플스테이 안내(자우당 법당);15:20~17:00 사찰 안내, 계곡 명상;17:00~17:30 저녁 공양;18:30~19:30 저녁 예불, 명상, 법문;19:30~21:00 자유시간(포행, 별바라기, 자율명상, 독서 등) 또는 스님과 차담;21:00~22:00 소등 후 취침;2일차;04:00~04:30 (자율) 새벽예불, 명상, 법문;05:00~06:30 (자율) 미륵전 해맞이;06:30~07:00 아침공양;07:00~09:30 자유시간(신선대 등반, 계곡 숲 걷기, 경내);09:30~10:30 (자율) 108배 염주 꿰기 및 소감문 작성;10:30~11:00 방사 정리 및 퇴소 준비;11:00~11:30 템플복 및 침구 반납 후 퇴소', '개인 세면도구(수건, 치약, 칫솔, 비누, 샴푸, 머리빗 등), 운동화(편한 신발), 양말, 개인 물병 등(헤어드라이기는 비치됨). 맨발, 민소매, 반바지 등의 복장은 삼가. 동절기에는 개인 방한용품', 70000, '1박 2일', '2017-08-01', '2026-11-01', 20, FALSE, 0, 0),
