    (165, '금강산에서  하루(당일형)', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_15750_S.webp', '화암사에 2~4시간 정도 머물면서 사찰 안내, 점심 공양, 스님과의 차담, 명상 등의 프로그램을 선택하여 진행합니다.

