    (165, '금강산 해맞이 명상(휴식형)', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_28335_S.webp', '- 화암사 휴식형 템플스테이는 자율적으로 몸과 마음의 휴식을 취하고 편안하게 자기 자신만의 시간을 갖는 프로그램으로, 사찰에서의 기본 예절은 지켜주시며 자유롭게 머물면서 화암사의 에너지를 충전하시면 됩니다.', '1일차;14:00~14:30 화암사 도착, 숙소 안내 및 환복;14:30~15:00 습의-입소 안내(자우당 법당);15:00~16:50 사찰 안내, 계곡 명상;17:00~17:30 저녁 공양;18:00~19:00 저녁 예불(대웅전);19:00~20:50 자유시간( 포행, 별바라기, 자율명상, 독서 등);21:00~21:30 소등 후 취침;2일차;04:00~04:30 (자율)새벽예불;05:00~06:30 (자율)미륵전 해맞이 또는 신선대 등반, 계곡 포행;06:30~07:00 아침공양;07:00~09:00 자유시간;09:00~10:30 (자율) 108배 염주 꿰기 및 소감문 작성;10:30~11:00 방사 정리 및 퇴소 준비;11:00~11:30 템플복 및 침구 반납 후 퇴소', '- 개인 세면도구(수건,치약, 칫솔,비누.샴푸.머리빗 등), 운동화(편한 신발), 개인 물병 (*헤어 드라이기는 비치) - 맨발,민소매,반바지 등의 복장은 삼가 주세요.  - 동절기에는 개인 방한용품을 챙겨주세요.', 70000, '1박 2일', '2018-07-31', '2026-11-02', 20, FALSE, 0, 0),
    (166, '[당일형] 산사의밥상', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_21457_S.webp', '화엄사에서 20년 넘는 경력을 가진 "마하연 보살님"의 사찰음식 강좌입니다. - 강사: 마하연 보살님 - 장소: 화엄사 사찰음식체험관 - 모집인원: 40명(선착순)', '1일차;13:00~15:00 사찰음식 강의', '만드신 음식을 담아 갈 컨테이너', 100000, '당일', '2022-03-07', '2027-12-31', 20, FALSE, 0, 0),
    (167, '나의 자유를 찾아서 (金 or 土 / 1박2일)', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/5/23/20250523094749693_1_S.webp', '바쁜 일상 속에서 좀처럼 쉴 수 없었던 마음 쉬어보기. 사찰의 차분한 분위기 속에서 예불, 공양, 운력 등 스님들의 일상 생활을 경험. 108배, 걷기 명상, 만다라 칠하기, 스님과의 차담 등을 통해 휴식과 충전의 시간을 가짐. 1인(동반자 포함) 1실 제공(개인욕실).', '1일차;14:30~15:00 접수;방사 배정;15:30~16:50 사찰습의 및 도량안내;17:00~17:30 저녁 공양;18:30~18:50 저녁 예불;19:00~19:30 108배(자율);21:00~06:00 소등;취침;2일차;05:30~06:00 새벽 예불(자율);07:00~07:30 아침 공양;07:30~08:30 걷기 명상(자율산책);08:30~09:30 스님과의 차담(자율);10:00~11:00 청소운력;귀가', '양말(하절기 포함), 물병(텀블러), 개인세면도구, 수건, 운동화, 우천시 우산, 편한 티셔츠(수련복은 조끼와 바지 제공), 겉옷', 80000, '1박 2일', '2024-09-27', '2026-12-31', 20, FALSE, 0, 0),
    (168, '" 마음의 쉼을 찾아서 " (휴식)', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/7/28/20250728043306255_1_S.webp', '바쁜 일상에서 벗어나 고요한 산사의 자연과 내면의 휴식을 즐기는 프로그램. 사찰안내와 기본적인 법당예절 습의 후, 스님과의 차담, 포행 등을 즐기며 자유롭게 사찰에서 휴식을 취할 수 있음. 성인만 참가 가능.', '1일차;14:00~15:00 입소 완료(템플사무실);16:00~17:00 사찰 안내;17:00~17:30 저녁 공양;17:45~18:15 저녁 예불;18:15~19:15 마음의 쉼-싱잉볼 명상(자율);19:15~21:00 휴식 및 취침;2일차;05:15~06:00 새벽 예불;06:30~07:00 아침 공양;08:00~10:30 천보산 등산 또는 회암사지 자율 포행;10:30~11:00 QR 작성 및 방사 정리, 템플복 반납', '개인 세면도구(수건, 칫솔, 치약 포함), 개인 물병, 여벌 속옷, 양말, 개인 티셔츠, 동절기 방한용품, 우천시 개인우산 (수련복은 사찰 제공)', 80000, '1박 2일', '2025-04-20', '2026-11-03', 20, FALSE, 0, 0),
    (168, '내려놓기, 진정한 나와의 만남~', '체험형', 'https://ts-cdn.com/ups/templePrg/2025/11/30/20251130034551204_1_S.webp', '붓다볼(싱잉볼) 명상체험을 통해 진정한 나를 바라보고, 무거운 기운을 내려놓으며 우주의 밝고 맑은 에너지를 느껴보는 프로그램. 스님과의 만남(상담)을 통해 고민과 힘든 상황을 직시하는 힘을 기르고, 사찰의 자연과 문화를 오감으로 느껴보는 시간. 성인, 중고등학생만 참가 가능.', '1일차;14:00~15:00 입소완료;16:00~17:00 사찰안내;17:00~17:30 저녁공양;17:45~18:15 저녁예불;18:15~19:15 붓다볼(싱잉볼) 명상;19:15~21:00 휴식 및 취침;2일차;05:15~06:00 새벽예불;06:30~07:00 아침공양;07:30~08:30 스님과의 만남(상담);08:30~10:30 천보산 등산 또는 회암사지 자율포행;10:30~11:00 QR작성, 방사정리, 템플복 반납', '개인 세면도구(수건, 칫솔, 치약 포함), 개인 물병, 여벌 속옷, 양말, 개인 티셔츠, 동절기 방한용품, 우천시 개인우산 (수련복은 사찰 제공)', 80000, '1박 2일', '2024-10-08', '2026-11-03', 20, FALSE, 0, 0),
    (168, '" 잠시 쉬어가는 시간 "', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_30299_S.webp', '바쁜 일상에서 잠시 멈춰 서서, 자신의 마음을 돌아보고 내면의 평화와 쉼을 찾는 시간입니다.
고요한 산사의 맑은 바람과 풍경 소리 속에서 마음을 정리하며 깊은 휴식을 경험하고, 온전히 나에게 집중하는 특별한 하루를 선물해 보세요
하루 동안 짧은 여정이지만 그 안에서 얻는 고요와 충만함은 당신의 삶에 따뜻한 울림을 더해줄 것입니다.
잠시 쉬어가는 시간— 당신의 하루를 가장 따뜻하고 의미 있는 휴식으로 채워드립니다.



* 본 프로그램은 예약 가능 여부를 확인한 후 승인이 가능합니다.
   입금요청 문자를 받으면 입금하시기 바랍니다.

