    (169, '참 나를 찾아서(체험형)', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/8/30/20260830115549089_4_S.webp', '신라시대 원효대사께서 북한산에서 수행하시던 중 노고산 자락에서 석조여래좌상(약사여래불)이 방광하는 것을 보시고 이곳을 찾아 절을 창건하였습니다. 지치고 힘든 현대인들의 몸과 마음의 치유를 위한 프로그램. 가족, 친구들과 함께 새로운 삶의 가치와 마음의 평화를 얻는 시간.', '1일차;14:00~14:30 접수 및 방사배정;14:50~15:30 연등만들기 & 사찰 기본예절;16:00~16:40 사찰안내;17:20~17:50 저녁 공양;18:15~19:10 타종체험 및 저녁예불;19:10~21:00 휴식, 자율;22:00~00:00 소등;2일차;05:00~05:40 새벽 예불 및 기도;05:50~06:20 아침 공양;07:30~08:20 스님과의 차담;08:20~08:40 염주만들기;08:40~10:00 자유시간 & 방사정리 후 회향', '개인 세면도구, 수건, 여벌옷, 양말, 개인보온물병, 동절기 모자·장갑·파카 등, 하절기 반팔티셔츠 (향수 사용 자제)', 90000, '1박 2일', '2024-01-01', '2026-11-30', 20, FALSE, 0, 0),
    (169, '마음에 쉼표를 찾다(휴식형)', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_9872_S.webp', '고요히 자신을 돌아보면서 쌓였던 스트레스와 각종 부담감을 털어내고 스스로에게 온전한 휴식과 안정의 시간을 제공해 주어 평안한 마음을 회복할 수 있는 기회.', '1일차;14:00~14:30 접수 및 방사배정;14:50~15:10 사찰기본예절교육;16:00~16:40 사찰안내;17:20~17:50 저녁 공양;18:15~19:10 타종체험 및 저녁예불;19:10~21:00 휴식, 자율;22:00~00:00 소등;2일차;05:00~05:40 새벽예불 및 기도(선택);05:50~06:20 아침 공양;06:30~09:30 휴식;09:30~10:00 방사정리 후 회향', '개인 세면도구, 수건, 여벌옷, 양말, 개인보온물병, 동절기 모자·장갑·파카 등, 하절기 반팔티셔츠 (향수 사용 자제)', 80000, '1박 2일', '2022-01-01', '2026-11-30', 20, FALSE, 0, 0),
    (169, '선명상스테이(체험형)', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/7/11/20260711104556957_1_S.webp', '온 몸을 감싸는 풍부하고 환희로운 호흡은 지금 여기를 실현하여 행복을 느끼고, 참 나를 만나게 하며, 틀 안에 갇힌 나를 해방시켜 번뇌로부터 탈출하게 하는 선명상 프로그램.', '1일차;14:00~14:30 접수 및 방사배정;14:40~15:10 사찰기본예절;15:10~15:50 염주 또는 연등만들기;16:00~16:50 사찰안내;17:20~17:50 저녁공양;18:15~19:10 타종체험 및 저녁예불;19:20~21:00 휴식, 자율;22:00~00:00 소등;2일차;05:00~05:40 새벽예불;05:50~06:20 아침공양;07:50~09:10 선명상이론과 실습;08:50~09:30 자유시간;09:30~10:00 방사정리 후 회향', '개인 세면도구, 수건, 여벌옷, 양말, 개인보온물병, 동절기 모자·장갑·파카 등, 하절기 반팔티셔츠 (향수 사용 자제)', 90000, '1박 2일', '2024-08-01', '2026-10-31', 20, FALSE, 0, 0),
    (169, '나를 찾는 시간여행 (당일형)', '당일형', 'https://ts-cdn.com/ups/templePrg/2025/4/5/20250405103138591_1_S.webp', '“나를 찾는 시간여행” 천년고찰 흥국사에서는 현대인들의 바쁜 일상생활에 지친 몸과 마음을 내려놓는 시간, 평일 짧은 시간이지만 나를 찾는 시간여행의 장을 마련했습니다.
