    (170, '[여수 섬섬박람회 특별기획]템플스테이와 함께하는 여수 크루즈 야경 불꽃쇼', '체험형', 'https://ts-cdn.com/ups/templePrg/2026/7/24/20260724054910668_1_S.webp', '다가오는 여수 섬섬박람회를 맞아 크루즈를 타고 여수 바다를 돌며, 시원한 바닷바람과 어두운 밤하늘 화려한 불꽃쇼를 바라보는 프로그램. 일상의 지침과 고난은 잠시 내려놓고 고요한 사찰에서 화려한 밤의 풍경까지 지친 마음에 활력을 채워넣는 템플스테이.', '1일차;15:00~15:20 입실(방사배정) 환복;15:20~16:00 문화해설사에게 듣는 흥국사 역사와 문화 이야기;17:00~17:30 저녁 공양;18:00~18:10 평상복 환복 및 모임장소 집합;18:10~18:20 크루즈 승선장으로 이동;19:30~21:00 크루즈 관광;21:10~22:00 사찰 복귀;2일차;05:00~05:30 새벽예불(자율);06:00~06:30 아침공양;07:00~08:00 자율 포행;08:00~10:00 소감문 작성 및 자유시간;10:00~10:30 방사정리 및 퇴실', '개인 세면도구(수건, 칫솔, 치약, 비누, 샴푸, 머리빗 등), 여벌옷, 운동화, 양말, 개인 보온물병(헤어드라이기 비치, 참가복 바지 제공), 동절기 방한용품', 120000, '1박 2일', '2026-08-01', '2026-12-31', 20, FALSE, 0, 0),
    (170, '108염주 만들기 , 다도체험(1박2일 체험형)', '체험형', 'https://ts-cdn.com/ups/old/RsImage/L_23506_S.webp', '천년 고찰 흥국사에서 문화 해설사가 들려주는 흥국사 문화재(보물 11점)에 얽힌 이야기와 해설로 불교 문화의 예술과 역사 문화적인 의미를 이해. 108염주를 만들고 108배를 체험하며 자신의 내면의 소리를 들어보는 프로그램. 다도 체험 포함(흥국사 템플스테이 체험자에게 여수시 낭만버스 무료 탑승권 증정).', '1일차;15:00~15:30 방사배정 환복;15:30~16:00 문화해설사에게 듣는 흥국사;16:00~16:50 휴식;17:00 저녁공양;17:30~18:30 염주 만들기, 다도(차담) 또는 108배 선택;21:00~00:00 취침;2일차;05:00~05:30 아침예불(자율);06:00 아침 공양;08:00~09:00 백팔돌탑포행(자율);10:00~11:00 소감문작성 퇴실', '개인 세면도구(수건, 칫솔, 치약, 비누, 샴푸, 머리빗 등), 여벌옷, 운동화, 양말, 개인 보온물병(헤어드라이기 비치, 참가복 조끼·바지 제공), 동절기 방한용품', 80000, '1박 2일', '2022-10-29', '2026-12-31', 20, FALSE, 0, 0),
    (170, '호국사찰에서 하룻밤(휴식형)', '휴식형', 'https://ts-cdn.com/ups/old/RsImage/L_29787_S.webp', '흥국사 휴식형 템플스테이는 모든 일정이 자율입니다. 천년의 유구한 역사를 몸과 마음으로 느낄 수 있고, 숲과 계곡 돌탑이 어우러져 발길 닿는 곳마다 자연과 하나가 되는 프로그램(흥국사 템플스테이 체험자에게 여수시 낭만버스 무료 탑승권 증정).', '1일차;14:30~15:00 오리엔테이션(사찰 예절, 주의사항);15:00~16:00 사찰안내;17:00 저녁공양;18:00 저녁 예불(자율);21:00~21:30 취침준비 및 취침;2일차;04:30~05:00 새벽예불(자율);06:00 아침공양;08:00~10:00 108돌탑길 명상(자율);10:00~10:30 방사정리 및 회향', '개인 세면도구(수건, 칫솔, 치약, 비누, 샴푸, 머리빗 등), 여벌옷, 운동화, 양말, 개인 보온물병(헤어드라이기 비치, 참가복 바지만 제공), 동절기 방한용품', 60000, '1박 2일', '2017-01-23', '2027-02-01', 20, FALSE, 0, 0),
    (170, '국궁과 사물체험(당일형)', '당일형', 'https://ts-cdn.com/ups/old/RsImage/L_3370_S.webp', '임진왜란때 사용 하였던 국궁을 체험해 봄으로써 호국 정신과.

 절에서 의식할때 사용하는 사물 (대종, 대북, 목어, 운판)을 체험해 보면서

  내 자신을 돌아보는 소중한 시간 입니다

( 최소 10인 이상 예약 가능합니다 )', '1일차;09:30~10:30 사찰도착 사찰안내및 사찰예절교육;10:30~11:30 프로그램 설명후 국궁 직접체험;11:30~12:30 점심공양;12:30~13:30 사물 (대종 대북 목어 운판) 직접체험;13:30~14:30 소감문 작성과 해단식', '당일형 프로그램의 경우 별도의 준비물이 필요 없습니다.
개인 물병 정도 준비하시면 됩니다.', 40000, '당일', '2016-12-07', '2026-12-31', 20, FALSE, 0, 0);


