(139, '성도절', '부처님께서 보리수 아래에서 깨달음을 이루신 것을 기념하는 불교 4대 명절 중 하나입니다.', '2025-01-07', '2025-01-07', 'https://www.jogyesa.kr'),
(160, '출가절', '부처님께서 세속의 삶을 떠나 수행자의 길로 들어선 것을 기념하는 불교 4대 명절 중 하나입니다.', '2025-03-07', '2025-03-07', 'http://www.haeinsa.or.kr/'),
(154, '열반절', '부처님께서 80세에 열반에 드신 것을 기념하는 불교 4대 명절 중 하나입니다.', '2025-03-14', '2025-03-14', 'https://www.tongdosa.or.kr/'),
