(69, '서울국제불교박람회', '국내 최대 규모의 불교 문화·용품 박람회로, 전국 사찰과 단체가 참가해 법요집·불교용품·전통차·사찰음식 등을 소개합니다. (서울 코엑스)', '2025-04-03', '2025-04-06', 'https://www.bexpo.kr/fair/2025bexpo'),
(143, '사직연등축제', '광주 사직공원 일대에서 열리는 연등 행사로, 봉축탑과 소원등 점등식, 작은 음악회가 함께 진행됩니다. (제7회)', '2025-04-14', '2025-05-06', 'https://www.startuptoday.co.kr/news/articleView.html?idxno=435287'),
(124, '용주사 연등음악축제', '화성시불교사암연합회와 용주사, 화성시가 함께 여는 행사로, 연등행렬과 체험부스, 저녁의 연등음악회로 이어집니다.', '2025-04-19', '2025-04-19', 'https://www.asiae.co.kr/article/2025041511193296546'),
(139, '연등축제 전통문화마당', '유네스코 인류무형문화유산 연등회 기간 중 열리는 전통문화 체험 행사로, 연등 만들기·전통차 시음·불교 공예 체험 등 다양한 부스가 운영됩니다.', '2025-04-26', '2025-04-27', 'https://www.jogyesa.kr'),
(69, '부처님오신날 연등법회', '부처님오신날을 봉축하는 연등법회와 점등식이 열립니다.', '2025-05-05', '2025-05-05', 'http://www.bongeunsa.org/'),
(160, '하안거 결제법회', '스님들이 여름 석 달간 한곳에 머물며 수행에 전념하는 하안거가 시작됩니다.', '2025-05-12', '2025-05-12', 'http://www.haeinsa.or.kr/'),
(59, '부산국제불교박람회', '부산 벡스코에서 열리는 영남권 최대 규모의 불교 문화·용품 박람회입니다.', '2025-08-07', '2025-08-10', 'http://busanbexpo.kr/'),
(139, '사찰음식 국제학술 심포지엄', '사찰음식의 국가무형유산 지정을 기념해 처음 열린 국제 학술 행사입니다. (국립고궁박물관 강당)', '2025-08-19', '2025-08-19', 'http://www.ibulgyo.com/news/articleView.html?idxno=440774'),
(154, '백중기도', '조상의 영가를 천도하고 은혜에 감사하는 백중(우란분절) 기도일이며, 같은 날 하안거 해제 법회도 함께 열립니다.', '2025-09-03', '2025-09-06', 'https://www.tongdosa.or.kr/'),
