(139, '행복두배 템플스테이', '문화체육관광부·한국관광공사와 연계해 전국 120여 개 사찰이 참여하는 템플스테이 참가비 반값 할인 캠페인입니다(1박2일 3만원, 외국인 대상 당일형 1만5천원).', '2026-05-01', '2026-05-31', 'https://www.templestay.com'),
(124, '용주사 연등음악축제', '화성시불교사암연합회와 용주사, 화성특례시가 함께 여는 행사로, 연등행렬과 체험부스, 저녁의 연등음악회로 이어집니다.', '2026-05-16', '2026-05-16', 'https://www.hsinews.com/51691'),
(139, '연등축제 전통문화마당', '유네스코 인류무형문화유산 연등회 기간 중 열리는 전통문화 체험 행사로, 연등 만들기·전통차 시음·불교 공예 체험 등 다양한 부스가 운영됩니다.', '2026-05-16', '2026-05-17', 'https://www.jogyesa.kr'),
(69, '부처님오신날 연등법회', '부처님오신날을 봉축하는 연등법회와 점등식이 열립니다.', '2026-05-24', '2026-05-24', 'http://www.bongeunsa.org/'),
(160, '하안거 결제법회', '스님들이 여름 석 달간 한곳에 머물며 수행에 전념하는 하안거가 시작됩니다.', '2026-05-31', '2026-05-31', 'http://www.haeinsa.or.kr/'),
(39, '대한민국불교문화엑스포', '대구 엑스코에서 열리는 불교문화 종합 박람회로, 전통문화 체험·법요용품 전시·반려동물 동반 프로그램 등이 함께 진행됩니다.', '2026-06-11', '2026-06-14', 'https://www.bexpodg.kr/'),
(59, '부산국제불교박람회', '부산 벡스코에서 열리는 영남권 최대 규모의 불교 문화·용품 박람회입니다.', '2026-08-06', '2026-08-09', 'http://busanbexpo.kr/'),
(139, '2026 사찰음식 국제학술 심포지엄', '한국·일본·이탈리아·미국 등 각국 전문가가 모여 사찰음식의 세계 음식문화로서의 가치를 논하는 국제 학술 행사입니다. (한국불교역사문화기념관)', '2026-08-20', '2026-08-20', 'http://www.ibulgyo.com/news/articleView.html?idxno=441389'),
(154, '백중기도', '조상의 영가를 천도하고 은혜에 감사하는 백중(우란분절) 기도일이며, 같은 날 하안거 해제 법회도 함께 열립니다.', '2026-08-24', '2026-08-27', 'https://www.tongdosa.or.kr/'),
(74, '추석 합동차례', '한가위를 맞아 대웅전에서 합동 차례와 감사 기도를 올립니다.', '2026-09-25', '2026-09-25', 'https://www.bulguksa.or.kr/'),
(166, '동안거 결제법회', '겨울 석 달간의 수행 정진이 시작되는 동안거 결제 법회입니다.', '2026-11-23', '2026-11-23', 'http://www.hwaeomsa.or.kr/'),

