(139, '정초기도', '새해를 맞아 한 해의 평안과 발원을 기원하는 정초 기도 법회입니다.', '2027-01-01', '2027-01-07', 'https://www.jogyesa.kr'),
(139, '성도절', '부처님께서 보리수 아래에서 깨달음을 이루신 것을 기념하는 불교 4대 명절 중 하나입니다. (음력-양력 환산값)', '2027-01-15', '2027-01-15', 'https://www.jogyesa.kr'),
(160, '출가절', '부처님께서 세속의 삶을 떠나 수행자의 길로 들어선 것을 기념하는 불교 4대 명절 중 하나입니다. (음력-양력 환산값)', '2027-03-15', '2027-03-15', 'http://www.haeinsa.or.kr/'),
(154, '열반절', '부처님께서 80세에 열반에 드신 것을 기념하는 불교 4대 명절 중 하나입니다. (음력-양력 환산값)', '2027-03-22', '2027-03-22', 'https://www.tongdosa.or.kr/'),
(69, '부처님오신날 연등법회', '부처님오신날을 봉축하는 연등법회와 점등식이 열립니다. (2027년 법정공휴일 지정일)', '2027-05-13', '2027-05-13', 'http://www.bongeunsa.org/'),
(160, '하안거 결제법회', '스님들이 여름 석 달간 한곳에 머물며 수행에 전념하는 하안거가 시작됩니다. (음력-양력 환산값)', '2027-05-20', '2027-05-20', 'http://www.haeinsa.or.kr/'),
(154, '백중기도', '조상의 영가를 천도하고 은혜에 감사하는 백중(우란분절) 기도일이며, 같은 날 하안거 해제 법회도 함께 열립니다. (음력-양력 환산값)', '2027-08-16', '2027-08-16', 'https://www.tongdosa.or.kr/'),
(74, '추석 합동차례', '한가위를 맞아 대웅전에서 합동 차례와 감사 기도를 올립니다.', '2027-09-15', '2027-09-15', 'https://www.bulguksa.or.kr/'),
(166, '동안거 결제법회', '겨울 석 달간의 수행 정진이 시작되는 동안거 결제 법회입니다. (음력-양력 환산값)', '2027-11-12', '2027-11-12', 'http://www.hwaeomsa.or.kr/');


-- #####################################################################
-- 6. 사찰음식 추천 (TEMPLE_FOOD_RECOMMENDATION)
-- #####################################################################
-- ============================================================
-- TEMPLE_FOOD_RECOMMENDATION(사찰음식 추천) 데이터 (20건)
--
-- "사찰 음식"(/info/food) 화면이 읽어가는 데이터입니다.
-- 20개 음식 전부 만개의레시피(10000recipe.com)에서 실제 존재하는 레시피를 하나씩 검색해서
-- 매칭했고, 그 링크를 recipe_url 컬럼에 저장합니다(추측/생성한 URL 아님).
-- ============================================================


INSERT INTO TEMPLE_FOOD_RECOMMENDATION (food_name, description, recipe, recipe_url, image_url) VALUES

('연근조림',
 '아삭한 식감과 은은한 단맛이 특징인 사찰음식의 기본 밑반찬입니다.',
 '1. 연근은 껍질을 벗겨 0.5cm 두께로 썬 뒤 식초물에 10분 담가 아린 맛을 뺀다.
2. 끓는 물에 연근을 3분 정도 데친다.
3. 냄비에 물, 간장, 조청(또는 매실청), 데친 연근을 넣고 중약불로 조린다.
4. 국물이 자작해지면 통깨를 뿌려 마무리한다.',
 'https://www.10000recipe.com/recipe/6250879', null),

('우엉조림',
 '쫄깃하게 씹히는 우엉을 간장 양념에 조려낸 사찰 대표 밑반찬입니다.',
 '1. 우엉은 필러로 껍질을 벗겨 얇게 채 썬 뒤 식초물에 담가 갈변을 막는다.
2. 팬에 들기름을 살짝 두르고 우엉을 볶다가 물을 부어 부드러워질 때까지 익힌다.
3. 간장, 조청을 넣고 국물이 거의 없어질 때까지 약불로 조린다.
4. 통깨를 뿌려 낸다.',
 'https://www.10000recipe.com/recipe/6872492', null),

('표고버섯장조림',
 '고기 대신 표고버섯으로 감칠맛을 낸 사찰음식의 대표 장아찌 반찬입니다.',
 '1. 마른 표고버섯을 미지근한 물에 불려 기둥을 떼고 먹기 좋게 썬다(불린 물은 육수로 재사용).
2. 냄비에 표고버섯 불린 물, 간장, 조청을 넣고 끓인다.
3. 손질한 표고버섯을 넣어 국물이 반으로 줄 때까지 약불로 졸인다.
4. 통깨와 참기름을 살짝 둘러 마무리한다.',
 'https://www.10000recipe.com/recipe/6906254', null),

('가지나물',
 '가지를 쪄서 양념에 무친, 부드럽고 담백한 여름 사찰음식입니다.',
 '1. 가지는 길게 반으로 갈라 김이 오른 찜기에서 5분간 찐다.
2. 한 김 식으면 손으로 결대로 찢는다.
3. 국간장, 다진 생강, 참기름, 통깨를 넣고 조물조물 무친다.',
 'https://www.10000recipe.com/recipe/6872357', null),

('취나물무침',
 '봄철 산나물인 취나물을 데쳐 된장으로 무친 향긋한 사찰음식입니다.',
 '1. 취나물은 억센 줄기를 다듬고 끓는 물에 소금을 약간 넣어 데친다.
2. 찬물에 헹궈 물기를 꼭 짠다.
3. 된장, 들기름, 다진 생강을 넣고 조물조물 무친다.
4. 마지막에 통깨를 뿌린다.',
 'https://www.10000recipe.com/recipe/6883949', null),

('산채비빔밥',
 '제철 나물과 고추장 대신 된장 양념을 곁들이는 사찰식 비빔밥으로, 오신채 없이도 깊은 맛을 냅니다.',
 '1. 고사리, 도라지, 시금치 등 나물을 각각 손질해 데치거나 볶아 양념한다.
2. 따뜻한 밥 위에 준비한 나물을 색 맞춰 올린다.
3. 된장이나 막장을 들기름에 개어 곁들인다.
4. 골고루 비벼 먹는다.',
 'https://www.10000recipe.com/recipe/6444047', null),

('도토리묵무침',
 '탱글탱글한 도토리묵에 채소를 곁들여 새콤하게 무친 여름철 사찰음식입니다.',
 '1. 도토리묵은 굵게 채 썰어 끓는 물에 살짝 데친 뒤 찬물에 헹궈 물기를 뺀다.
2. 오이, 당근 등 채소를 얇게 채 썬다.
3. 간장, 식초, 조청, 참기름을 섞어 양념장을 만든다.
4. 묵과 채소에 양념장을 넣고 살살 버무린 뒤 통깨를 뿌린다.',
 'https://www.10000recipe.com/recipe/6979751', null),

('고사리나물',
 '불려서 삶은 고사리를 들기름에 볶아낸, 명절상에도 자주 오르는 사찰 밑반찬입니다.',
 '1. 마른 고사리를 물에 불린 뒤 억센 밑동을 잘라내고 먹기 좋은 길이로 썬다.
2. 팬에 들기름을 두르고 고사리를 볶다가 국간장을 넣어 간을 맞춘다.
3. 물을 약간 부어 뚜껑을 덮고 중약불로 부드러워질 때까지 익힌다.
4. 다진 생강과 통깨를 넣어 마무리한다.',
 'https://www.10000recipe.com/recipe/6926103', null),

('애호박전',
 '얇게 썬 애호박에 부침옷을 입혀 기름에 지진 담백한 사찰음식입니다.',
 '1. 애호박은 0.5cm 두께로 둥글게 썰어 소금을 살짝 뿌려 절인다.
2. 물기를 닦은 애호박에 밀가루를 얇게 입힌다.
3. 밀가루, 물, 소금을 섞어 만든 반죽을 애호박에 묻힌다.
4. 팬에 기름을 두르고 노릇하게 앞뒤로 지진다.',
 'https://www.10000recipe.com/recipe/6868919', null),

('콩나물무침',
 '아삭한 콩나물을 삶아 양념에 무친, 가장 기본적인 사찰 밑반찬입니다.',
 '1. 콩나물은 씻어 냄비에 소금을 약간 넣고 뚜껑을 덮은 채 삶는다.
2. 삶은 콩나물은 찬물에 헹궈 물기를 뺀다.
3. 국간장, 다진 생강, 참기름, 통깨를 넣고 무친다.',
 'https://www.10000recipe.com/recipe/6856251', null),

('된장찌개',
 '멸치나 육수 없이 채수만으로 깊은 맛을 낸 사찰식 된장찌개입니다.',
 '1. 다시마와 표고버섯을 물에 넣고 끓여 채수를 낸다.
2. 채수에 된장을 풀고 두부, 애호박, 감자를 넣어 끓인다.
3. 재료가 익으면 청양고추를 약간 넣어 칼칼하게 마무리한다.',
 'https://www.10000recipe.com/recipe/6850626', null),

('김부각',
 '김에 찹쌀풀을 발라 말린 뒤 튀겨낸, 바삭한 식감의 사찰 별미 반찬입니다.',
 '1. 김 한 장에 찹쌀풀을 얇게 바른 뒤 다른 김 한 장을 겹쳐 덮는다.
2. 통깨를 뿌려 채반에 널어 완전히 말린다.
3. 먹기 좋은 크기로 잘라 170도 기름에 짧게 튀긴다.
4. 기름을 빼고 소금을 살짝 뿌린다.',
 'https://www.10000recipe.com/recipe/6898139', null),

('시래기나물',
 '무청을 말려 불린 시래기를 들깨와 함께 볶아낸, 구수한 맛의 사찰 밑반찬입니다.',
 '1. 마른 시래기를 물에 충분히 불린 뒤 삶아 질긴 껍질을 벗기고 먹기 좋게 썬다.
2. 팬에 들기름을 두르고 시래기를 볶다가 국간장으로 밑간한다.
3. 들깻가루와 물을 넣고 뚜껑을 덮어 약불로 자작하게 조린다.',
 'https://www.10000recipe.com/recipe/6884751', null),

('두부조림',
 '단백한 두부를 매콤달콤한 양념에 조린 사찰음식의 대표 단백질 반찬입니다.',
 '1. 두부는 도톰하게 썰어 팬에 기름을 살짝 두르고 앞뒤로 노릇하게 지진다.
2. 간장, 조청, 고춧가루, 다진 생강을 섞어 양념장을 만든다.
3. 지진 두부에 양념장을 끼얹고 물을 약간 부어 약불로 조린다.
4. 통깨와 다진 청양고추로 마무리한다.',
 'https://www.10000recipe.com/recipe/6688343', null),

('미나리무침',
 '향긋한 미나리를 살짝 데쳐 새콤하게 무친 봄철 사찰음식입니다.',
 '1. 미나리는 다듬어 끓는 물에 소금을 약간 넣고 짧게 데친다.
2. 찬물에 헹궈 물기를 꼭 짠 뒤 먹기 좋은 길이로 썬다.
3. 국간장, 식초, 참기름, 통깨를 넣고 가볍게 무친다.',
 'https://www.10000recipe.com/recipe/6863267', null),

('감자조림',
 '한입 크기로 썬 감자를 간장 양념에 윤기 나게 조린 사찰 밑반찬입니다.',
 '1. 감자는 한입 크기로 썰어 물에 담가 전분기를 뺀다.
2. 팬에 감자와 물, 간장, 조청을 넣고 중불로 끓인다.
3. 국물이 자작해지면 약불로 줄여 윤기가 나도록 조린다.
4. 통깨를 뿌려 마무리한다.',
 'https://www.10000recipe.com/recipe/6852611', null),

('배추전',
 '배춧잎에 부침옷을 살짝 입혀 지진, 달큰하고 담백한 사찰 별미입니다.',
 '1. 배추는 잎 부분만 떼어 소금물에 살짝 절인다.
2. 밀가루, 물, 소금을 섞어 묽은 반죽을 만든다.
3. 절인 배추에 반죽을 얇게 입혀 팬에 노릇하게 지진다.',
 'https://www.10000recipe.com/recipe/6879390', null),

('단호박죽',
 '푹 삶은 단호박을 곱게 갈아 끓인, 속을 편안하게 해주는 사찰 별식입니다.',
 '1. 단호박은 씨를 제거하고 큼직하게 썰어 푹 찐다.
2. 찐 단호박을 물과 함께 곱게 간다.
3. 냄비에 옮겨 끓이면서 찹쌀가루 물을 조금씩 넣어 농도를 맞춘다.
4. 소금으로 간을 살짝 맞춘다.',
 'https://www.10000recipe.com/recipe/6856733', null),

('죽순나물',
 '아삭하게 씹히는 죽순을 들기름에 볶아낸 봄철 사찰음식입니다.',
 '1. 삶은 죽순은 얇게 빗살무늬로 썬다.
2. 팬에 들기름을 두르고 죽순을 볶다가 국간장으로 간한다.
3. 물을 약간 넣고 뚜껑을 덮어 부드러워질 때까지 익힌다.
4. 통깨를 뿌려 낸다.',
 'https://www.10000recipe.com/recipe/6883933', null),

('열무김치',
 '젓갈 없이 채수와 고춧가루로만 맛을 낸 사찰식 열무김치입니다.',
 '1. 열무는 손질해 소금에 절인 뒤 헹궈 물기를 뺀다.
2. 밀가루풀에 고춧가루, 다진 생강, 매실청을 섞어 양념을 만든다.
3. 절인 열무에 양념을 버무려 하루 정도 실온에서 숙성시킨다.
4. 이후 냉장 보관하며 먹는다.',
 'https://www.10000recipe.com/recipe/6933967', null);


