(98, 'testuser1', 338, '2026-07-03', '2026-07-04', 1, NULL, '이용완료', NULL, '[체험형/휴식형] 자연에서 나를 찾고, 나를 알고, 나를 본다. 서울 도봉산 천축사 고!고! (체험형, 휴식형은 프로그램 참여 선택 가능)', '천축사'),
